/**
 * Submission lifecycle service (canonical core)
 *
 * CRUD + lifecycle transitions for the canonical submission core
 * (`submissions` / `ectd_sequences` / `submission_leaves`). This is the service
 * the spec §8.2 lists first — until now the core had NO service and NO API; it
 * was written only by ingestion and read by nobody.
 *
 * Every read/write is tenant-scoped from the caller's organizationId (never from
 * request input) and every mutation is audited. Lifecycle-state rules are pure
 * functions (testable without a DB).
 *
 * @module server/services/submission-service/submission-service
 */

import { createHash, randomUUID } from 'crypto';
import { eq, and, isNull, desc, sql } from 'drizzle-orm';
import { drizzle } from 'drizzle-orm/node-postgres';
import type { PoolClient } from 'pg';
import { db, pool } from '../../db';
import {
  submissions,
  ectdSequences,
  submissionLeaves,
  coauthorDocuments,
} from '../../../shared/schema';
import { renderedLeafFiles } from '../../../shared/schema/submissions';
import { unifiedDocuments, workflowDocumentVersions } from '../../../shared/schema/unified_workflow';
import { ctdOnboardingDocuments } from '../../../shared/schema/ctd-projects';
import { readLocalUploadBuffer } from '../anthropic-files';
import { sectionPlainText } from '../c2c/section-content';
import {
  externalDocumentTableReason,
  isPlaceableDocumentTable,
  unplaceableDocumentTableMessage,
} from '../ectd/leaf-document-tables';
import type {
  Submission,
  EctdSequence,
  SubmissionLeaf,
} from '../../../shared/types/database';
import { writeChainedAuditRow } from '../auditService';
import { recordAuditRow, type AuditRowOutcome } from '../audit/audit-write-outcome';
import {
  deriveGovernedTargetBinding,
  BINDING_BASIS,
  isSignatureWithdrawn,
  voidSignatureForRefusedAct,
  VOIDED_VERIFICATION_STATUS,
} from '../part11/signature-persistence';
import { releaseActMeaningRefusal } from '../part11/signature-meanings';
import { createScopedLogger } from '../../utils/logger';
import { isFiledDispatchStatus } from './filed-dispatch';
import { canMutateProgram, programInOrganization } from '../c2c/program-access';
import {
  assertSignerIsNotAuthor,
  requiresIndependence,
  SeparationOfDutiesAuthorUnresolvedError,
  SeparationOfDutiesError,
} from '../governance/separation-of-duties';
import {
  SHADOW_REVIEW_WAIVED_ACTION,
  SHADOW_WAIVER_INTENT,
  completedShadowReviewRuns,
  evaluateShadowPresenceWithWaiver,
  resolveShadowReviewWaiver,
  shadowReviewWaivable,
  shadowWaiverInsert,
  shadowWaiverMeaningRefusal,
  shadowWaiverRunRefusal,
  type ShadowReviewWaivability,
  type ShadowReviewWaiverRecord,
} from '../ectd/shadow-review-waiver';
import {
  SHADOW_FINDING_DISPOSITIONED_ACTION,
  SHADOW_FINDING_DISPOSITION_INTENT,
  criticalsStandingOpen,
  reopenedCriticalSentence,
  dispositionSignatureReason,
  isShadowFindingDisposition,
  readShadowFindingDisposition,
  shadowFindingDisposable,
  shadowFindingDispositionMeaningRefusal,
  shadowFindingDispositionPayloadRefusal,
  shadowFindingDispositionRefusal,
  shadowFindingDispositionUpdate,
  type ShadowFindingDisposability,
  type ShadowFindingDispositionRecord,
  type ShadowFindingDispositionRequest,
} from '../ectd/shadow-finding-disposition';
import { isWaivableShadowReviewFailure } from '../../../shared/constants/shadow-review-failure';
import { isSameSubmissionType, resolveToRegistryEntry } from '../../../shared/regulatory/submission-type-bridge';
import { cespChannelRefusal } from '../submission-gateways/ema-cesp';
import { usableIdentifier } from '../ectd/regulatory-identifiers';
import { packageIdentityRefusal, readRecordedPackageIdentity } from '../ectd/package-identity';
import type { DispatchReadinessAssessment } from '../ectd/assess-dispatch-readiness';
import { submissionChannelFor } from '../regulatory/registry/submittabilityCoverage';
import { sequenceTypeRefusal } from '../regulatory/market-support';
import { canonicalRegionOf, toAgency } from '../../../shared/regulatory/region-identity';
import { regionalDeviceApplicationClassOf } from '../../../shared/regulatory/filing-catalog';
import { companyLegalVaultTargetRefusal } from '../vault/vault-lifecycle';
import { setTenantContextTx } from '../tenant/governed-tenant-context';
import {
  validateSectionCode,
  vocabularyForApplicationType,
  type PlacementVocabulary,
} from '../../../shared/regulatory/placement-vocabulary';

const logger = createScopedLogger('submission-service');

// ── Standardized errors ───────────────────────────────────────────────────────

export type SubmissionErrorCode =
  | 'NOT_FOUND'
  | 'INVALID_STATE'
  | 'VALIDATION'
  | 'GOVERNED_REQUIRED'
  | 'DISPATCH_BLOCKED'
  | 'FORBIDDEN'
  | 'CROSS_PROJECT'
  | 'ALREADY_PLACED'
  | 'VALIDATION_FAILED'
  | 'UNANCHORED_SUBMISSION'
  | 'APPLICATION_NUMBER_MISMATCH'
  | 'APPLICATION_TYPE_MISMATCH'
  | 'DEVICE_PREPARATION_ONLY'
  | 'PACKAGE_IDENTITY_MISSING'
  | 'SHADOW_WAIVER_NOT_ELIGIBLE'
  | 'SHADOW_FINDING_NOT_DISPOSABLE';

/**
 * Transitions that are irreversible / outward-facing and must go through the
 * governed e-signature flow (POST /api/c2c/actions sign) — they are NOT allowed
 * via the generic transition endpoint (Part 11, spec §10).
 */
const GOVERNED_TRANSITIONS = new Set(['frozen', 'dispatched']);

export class SubmissionError extends Error {
  constructor(public code: SubmissionErrorCode, message: string) {
    super(message);
    this.name = 'SubmissionError';
  }
}

/**
 * The HTTP status each refusal carries, wherever a route surfaces one. Typed
 * over the code union so a new code cannot ship unmapped — an unmapped refusal
 * is a 500, which tells the caller the server broke when it did not.
 */
export const SUBMISSION_ERROR_STATUS: Readonly<Record<SubmissionErrorCode, number>> = {
  NOT_FOUND: 404,
  INVALID_STATE: 409,
  VALIDATION: 400,
  GOVERNED_REQUIRED: 403,
  DISPATCH_BLOCKED: 422,
  FORBIDDEN: 403,
  CROSS_PROJECT: 409,
  ALREADY_PLACED: 409,
  VALIDATION_FAILED: 422,
  DEVICE_PREPARATION_ONLY: 422,
  UNANCHORED_SUBMISSION: 409,
  // The status the eCTD export answers for the same contradiction (ectd-export.ts).
  APPLICATION_NUMBER_MISMATCH: 409,
  // A submission anchored only to a project of its own filing type (QA j6).
  APPLICATION_TYPE_MISMATCH: 409,
  // The record names no application number or no applicant (QA j6), as the
  // eCTD export answers it (ectd-export.ts classifyError).
  PACKAGE_IDENTITY_MISSING: 409,
  // No Shadow Review waiver is on offer for this sequence (P-34): no outage is
  // recorded on its newest run, or a review already completed, or it is frozen.
  SHADOW_WAIVER_NOT_ELIGIBLE: 409,
  // The finding cannot be closed this way now (P-35): it is not an open critical
  // of this sequence, or 'fixed' was asked with no completed review after it.
  SHADOW_FINDING_NOT_DISPOSABLE: 409,
};

// ── Pure lifecycle rules ────────────────────────────────────────────────────

export const SEQUENCE_STATUSES = ['draft', 'assembling', 'validated', 'frozen', 'dispatched'] as const;
export type SequenceStatus = (typeof SEQUENCE_STATUSES)[number];

/** Allowed forward transitions for a sequence's status. */
const SEQUENCE_TRANSITIONS: Record<SequenceStatus, SequenceStatus[]> = {
  draft: ['assembling'],
  assembling: ['validated', 'draft'],
  validated: ['frozen', 'assembling'],
  frozen: ['dispatched'],
  dispatched: [],
};

/** Whether a sequence may move from `from` to `to`. Pure. */
export function canTransitionSequence(from: string, to: string): boolean {
  const allowed = SEQUENCE_TRANSITIONS[from as SequenceStatus];
  return Array.isArray(allowed) && allowed.includes(to as SequenceStatus);
}

/** A frozen or dispatched sequence is immutable — its leaves cannot change. Pure. */
export function isSequenceLocked(status: string): boolean {
  return status === 'frozen' || status === 'dispatched';
}

// ── Submissions ───────────────────────────────────────────────────────────────

export interface CreateSubmissionInput {
  title: string;
  productName?: string | null;
  applicationType: string;
  clientType: string;
  primaryRegion: string;
  lifecycleStage?: string;
  /** The project this submission belongs to (regulatory_programs.id). Checked
   *  against the caller's organization before anything is written. Optional
   *  here; POST /api/submissions requires it, and intake always passes it. */
  programId?: string | null;
}

/** Anything that can run the canonical submissions INSERT — the pool-backed
 *  `db`, or a per-request drizzle wrapper over a transaction's PoolClient. */
type SubmissionInsertExecutor = Pick<typeof db, 'insert'>;

/**
 * The ONE definition of what a canonical `submissions` row is created from.
 * Both creation paths (standalone `createSubmission`, transactional
 * `createSubmissionTx`) run through here so the field mapping cannot fork.
 */
async function insertSubmissionRow(
  executor: SubmissionInsertExecutor,
  input: CreateSubmissionInput,
  ctx: { organizationId: number; userId: number }
): Promise<Submission> {
  if (regionalDeviceApplicationClassOf(input.applicationType)) {
    throw new SubmissionError('DEVICE_PREPARATION_ONLY',
      'Start this filing as an authoring project. Its preparation outline does not support canonical submission creation yet. Nothing was created.');
  }
  const [row] = await executor
    .insert(submissions)
    .values({
      title: input.title,
      productName: input.productName ?? null,
      applicationType: input.applicationType,
      clientType: input.clientType,
      primaryRegion: input.primaryRegion,
      lifecycleStage: input.lifecycleStage ?? 'planning',
      organizationId: ctx.organizationId,
      createdBy: ctx.userId,
      programId: input.programId ?? null,
    })
    .returning();
  return row as Submission;
}

/**
 * A submission is anchored only to a live project of its OWN organization
 * (LX-22). Refused as NOT_FOUND (404), before anything is written — 404 rather
 * than 403, so the caller learns nothing about another tenant's ids. The
 * same-organization foreign key (submissions_program_same_org_fk) is the
 * database backstop; it does not see a deleted project, and its 23503 would
 * reach the caller as a 500, so it is never the first line.
 */
async function refuseForeignProgram(
  q: Parameters<typeof programInOrganization>[0],
  programId: string | null | undefined,
  organizationId: number,
): Promise<void> {
  if (programId === undefined || programId === null) return;
  if (!(await programInOrganization(q, programId, organizationId))) {
    throw new SubmissionError('NOT_FOUND', 'Project not found for this organization.');
  }
}

/**
 * A created submission, with what happened to the 21 CFR Part 11 §11.10(e)
 * record of its creation carried on it.
 *
 * WO-16C #133. The audit write below was `await auditService.logAction({…})` at
 * statement position, which discards the `AuditWriteResult` that call resolves.
 * `logAction` never rejects when persistence fails — by deliberate policy, an
 * audit-trail outage must not break the action it records — so awaiting it and
 * throwing the value away reported exactly as much as not awaiting it: the
 * `submissions` row was committed and the caller (POST /api/submissions, which
 * returns this object as its 201 body) was handed a byte-identical success
 * whether the §11.10(e) record for creating this application existed or not.
 *
 * The inserted row is returned intact with `auditTrail` added, so callers that
 * read `id` / `title` / `applicationType` off it are unaffected and the outcome
 * travels with it. `auditTrail` is the key this repository already uses for a
 * service's own row (`CreatedQSubmission.auditTrail` in
 * server/services/q-sub/q-sub.service.ts).
 */
export type CreatedSubmission = Submission & { auditTrail: AuditRowOutcome };

export async function createSubmission(
  input: CreateSubmissionInput,
  ctx: { organizationId: number; userId: number }
): Promise<CreatedSubmission> {
  if (input.programId != null) await refuseForeignProgram(pool, input.programId, ctx.organizationId);
  const row = await insertSubmissionRow(db, input, ctx);
  // Part 11 §11.10(e). `recordAuditRow` neither throws nor rejects, and the
  // INSERT above is already committed when it runs, so the submission stands
  // either way and is never un-created over a lost log row — this is a record
  // beside a committed change, not the change itself. What changes is that the
  // caller is told, in `auditTrail`. The store's own reason for a failure stays
  // in the log line recordAuditRow wrote against this action and resource id;
  // `message` on the failure arm is the only text fit to show a user.
  const auditTrail = await recordAuditRow({
    organizationId: ctx.organizationId,
    userId: ctx.userId,
    action: 'SUBMISSION_CREATED',
    resourceType: 'submission',
    resourceId: row.id,
    details: {
      applicationType: input.applicationType,
      primaryRegion: input.primaryRegion,
      clientType: input.clientType,
      programId: input.programId ?? null,
    },
  });
  logger.info('Created submission', { submissionId: row.id, organizationId: ctx.organizationId });
  return { ...row, auditTrail };
}

/**
 * Create a canonical submission INSIDE a caller-owned transaction.
 *
 * Runs the same INSERT as `createSubmission`, but on the caller's PoolClient,
 * so the submission commits — or rolls back — atomically with whatever else
 * that transaction creates (e.g. the regulatory program the C2C intake wizard
 * writes in routes/c2c/projects.ts). Mirrors the `createSubmissionTx(client,…)`
 * idiom in services/irb/irb-service.ts.
 *
 * Deliberately does NOT call auditService.logAction: that write runs on its own
 * pooled connection, OUTSIDE the caller's transaction, so on rollback it would
 * leave a sealed record of a submission that does not exist — a fabricated
 * audit trail. The caller owns the transaction and must write its own audit row
 * on the same client (the C2C intake route writes a hash-chained audit_logs row
 * covering both creations).
 */
export async function createSubmissionTx(
  client: PoolClient,
  input: CreateSubmissionInput,
  ctx: { organizationId: number; userId: number }
): Promise<Submission> {
  // On the caller's client, so a project inserted earlier in the same
  // uncommitted transaction (intake) is seen.
  await refuseForeignProgram(client, input.programId, ctx.organizationId);
  return insertSubmissionRow(drizzle(client), input, ctx);
}

/**
 * The organization's live submissions, newest first. With `scope.programId`, only
 * the submissions anchored to that program (submissions.program_id): an
 * unanchored submission (NULL) belongs to no program and is not in that list. The
 * filing picker reads the scoped list; the Submission Center and Dispatch
 * Readiness read the whole organization.
 */
export async function listSubmissions(
  ctx: { organizationId: number },
  scope?: { programId?: string },
): Promise<Submission[]> {
  const rows = await db
    .select()
    .from(submissions)
    .where(
      and(
        eq(submissions.organizationId, ctx.organizationId),
        isNull(submissions.deletedAt),
        scope?.programId ? eq(submissions.programId, scope.programId) : undefined,
      ),
    )
    .orderBy(desc(submissions.updatedAt));
  return rows as Submission[];
}

export async function getSubmission(
  id: number,
  ctx: { organizationId: number }
): Promise<Submission> {
  const [row] = await db
    .select()
    .from(submissions)
    .where(and(eq(submissions.id, id), eq(submissions.organizationId, ctx.organizationId), isNull(submissions.deletedAt)))
    .limit(1);
  if (!row) throw new SubmissionError('NOT_FOUND', 'Submission not found for this organization.');
  return row as Submission;
}

// ── Anchoring a submission to its project (P-14's remedy) ───────────────────

/** Who is anchoring: the caller, with their organisation role from the membership row. */
export type AnchorContext = { organizationId: number; userId: number; orgRole: string | null };

/**
 * The live leaves of a submission whose document belongs to a project other
 * than `programId`, described for a refusal ("sequence 0000, m5.3.5"). A leaf
 * whose store records no project is not judged, as at placement.
 */
async function leavesOfAnotherProgram(submissionId: number, programId: string, organizationId: number): Promise<string[]> {
  const res = await pool.query(
    `SELECT s.sequence_number, l.section_code, l.document_table, l.document_id, l.document_uuid
       FROM submission_leaves l
       JOIN ectd_sequences s ON s.id = l.sequence_id AND s.organization_id = l.organization_id
      WHERE s.submission_id = $1 AND s.organization_id = $2 AND s.deleted_at IS NULL
        AND l.deleted_at IS NULL AND l.document_table IS NOT NULL
      ORDER BY s.sequence_number, l.section_code`,
    [submissionId, organizationId],
  );
  type Row = { sequence_number: string; section_code: string; document_table: string; document_id: number | null; document_uuid: string | null };
  const foreign: string[] = [];
  for (const l of (res.rows ?? []) as Row[]) {
    const owner = await leafSourceProgram(
      l.document_table,
      { documentId: l.document_id ?? null, documentUuid: l.document_uuid ?? null },
      organizationId,
    );
    if (owner && owner !== programId) foreign.push(`sequence ${l.sequence_number}, ${l.section_code}`);
  }
  return foreign;
}

/**
 * Anchor a submission that records no project to one (P-14,
 * docs/LAUNCH_DEFINITION_OF_DONE.md, 2026-10-08: "A legacy submission with no
 * program is anchored first, through the Submission Center, and then accepts
 * placements"). Until this, nothing wrote submissions.program_id after creation,
 * so the UNANCHORED_SUBMISSION refusal had no remedy.
 *
 * Refused, with nothing changed:
 *   - NOT_FOUND: the submission, or the project, is not a live record of the
 *     caller's organization (programInOrganization, the one tenancy answer);
 *   - FORBIDDEN: the caller neither leads the project nor manages the
 *     organization (canMutateProgram, the rule for changing a project's
 *     records). Anchoring makes the project's documents placeable here and puts
 *     this filing under the project's recorded application number;
 *   - INVALID_STATE: the submission already has a project. A project holds
 *     several submissions (one per market), so there is no "one submission per
 *     project" rule; what is not done here is moving a filing between projects;
 *   - CROSS_PROJECT: the submission already files another project's document,
 *     placed before P-14 refused it. A filing holds only its own project's
 *     documents (PF-11), so those leaves are removed first;
 *   - APPLICATION_TYPE_MISMATCH: the project files another kind of application
 *     than the submission (isSameSubmissionType, the shared submission-type
 *     resolution; never a name). QA 2026-10-08 (j6): the control offered a
 *     device programme for an NDA, the server checked no type, and an anchor
 *     is not undone here. listAnchorCandidates offers only what this admits.
 * The update is a compare-and-set on program_id IS NULL, and it commits with
 * its chained SUBMISSION_PROGRAM_ANCHORED audit row, carrying the reason, or
 * neither does (§11.10(e)).
 */
export async function anchorSubmissionToProgram(
  input: { submissionId: number; programId: string; reason: string },
  ctx: AnchorContext,
): Promise<Submission> {
  const reason = input.reason.trim();
  if (!reason) throw new SubmissionError('VALIDATION', 'A reason for anchoring the submission is required. Nothing was changed.');
  const current = await getSubmission(input.submissionId, ctx);
  if (current.programId) throw alreadyAnchoredRefusal(current.programId, input.programId);
  await assertMayAnchorTo(input.programId, current.applicationType, ctx);
  const foreign = await leavesOfAnotherProgram(input.submissionId, input.programId, ctx.organizationId);
  if (foreign.length > 0) throw foreignLeavesRefusal(foreign);
  await writeSubmissionAnchor(input.submissionId, input.programId, reason, ctx);
  logger.info('Anchored submission to its project', {
    submissionId: input.submissionId, programId: input.programId, organizationId: ctx.organizationId,
  });
  return getSubmission(input.submissionId, ctx);
}

/** A submission that has a project keeps it: anchoring is not a move between projects. */
function alreadyAnchoredRefusal(current: string, requested: string): SubmissionError {
  return new SubmissionError(
    'INVALID_STATE',
    current === requested
      ? 'This submission is already anchored to that project. Nothing was changed.'
      : 'This submission is already anchored to another project, and a submission is not moved between projects here. Nothing was changed.',
  );
}

/**
 * The project is a live one of this organization, files the submission's kind
 * of application, and the caller leads it or manages the organization. The type
 * is judged before the role, so a wrong choice is told what is wrong with it.
 */
async function assertMayAnchorTo(programId: string, applicationType: string, ctx: AnchorContext): Promise<void> {
  if (!(await programInOrganization(pool, programId, ctx.organizationId))) {
    throw new SubmissionError('NOT_FOUND', 'Project not found for this organization. Nothing was changed.');
  }
  const lead = await pool.query(
    `SELECT lead_user_id, program_type, code FROM regulatory_programs WHERE id = $1 AND organization_id = $2`,
    [programId, ctx.organizationId],
  );
  const program = lead.rows[0] as { lead_user_id?: unknown; program_type?: string | null; code?: string | null } | undefined;
  if (!isSameSubmissionType(program?.program_type, applicationType)) {
    throw applicationTypeMismatch(applicationType, program?.program_type ?? null, program?.code ?? null);
  }
  const raw = program?.lead_user_id;
  const leadUserId = raw == null ? null : Number(raw);
  if (!canMutateProgram({ actor: { userId: ctx.userId, orgRole: ctx.orgRole }, program: { leadUserId } })) {
    throw new SubmissionError(
      'FORBIDDEN',
      'Only the project’s lead or an organization manager can anchor a submission to it. Nothing was changed.',
    );
  }
}

/** A filing type as the reader knows it ('NDA', '510(k)'), from the shared registry; the raw value when unknown. */
const filingTypeLabel = (t: string | null): string => (t ? resolveToRegistryEntry(t)?.applicationType ?? t : 'not recorded');

function applicationTypeMismatch(applicationType: string, programType: string | null, code: string | null): SubmissionError {
  return new SubmissionError(
    'APPLICATION_TYPE_MISMATCH',
    `This submission's filing type is ${filingTypeLabel(applicationType)}; project${code ? ` ${code}` : ''}'s is ` +
      `${filingTypeLabel(programType)}, so the submission cannot be anchored to it. Choose a project of the same filing type. ` +
      'Nothing was changed.',
  );
}

export interface AnchorCandidates {
  /** submissions.application_type, the type a candidate must file. */
  applicationType: string;
  /** That type as the reader knows it ('NDA', '510(k)'), from the shared registry. */
  applicationTypeLabel: string;
  /** This organization's live projects of that type, ordered by code. */
  candidates: Array<{ id: string; code: string; title: string }>;
  /** Live projects of other filing types: counted, never named. */
  otherTypes: number;
}

/**
 * The projects a submission may be anchored to: this organization's live
 * projects (not deleted, as programInOrganization reads them) whose type is the
 * submission's (isSameSubmissionType, the rule the anchor applies). The Submission Center offers exactly these; the anchor still
 * judges type, role and leaves itself. NOT_FOUND for another organization's
 * submission (getSubmission).
 */
export async function listAnchorCandidates(
  submissionId: number,
  ctx: { organizationId: number; userId: number },
): Promise<AnchorCandidates> {
  const current = await getSubmission(submissionId, ctx);
  const rows = (
    await pool.query(
      `SELECT id::text AS id, code, name, program_type FROM regulatory_programs
        WHERE organization_id = $1 AND deleted_at IS NULL
        ORDER BY code, name, id`,
      [ctx.organizationId],
    )
  ).rows as Array<{ id: string; code: string | null; name: string | null; program_type: string | null }>;
  const same = rows.filter((r) => isSameSubmissionType(r.program_type, current.applicationType));
  return {
    applicationType: current.applicationType,
    applicationTypeLabel: filingTypeLabel(current.applicationType),
    candidates: same.map((r) => ({ id: r.id, code: r.code ?? '', title: r.name ?? '' })),
    otherTypes: rows.length - same.length,
  };
}

/** The refusal for a submission that already files another project's documents. */
function foreignLeavesRefusal(foreign: string[]): SubmissionError {
  const what = foreign.length === 1 ? 'a document' : `${foreign.length} documents`;
  const more = foreign.length > 5 ? `; and ${foreign.length - 5} more` : '';
  return new SubmissionError(
    'CROSS_PROJECT',
    `This submission already files ${what} of another project (${foreign.slice(0, 5).join('; ')}${more}). A filing holds only ` +
      'its own project’s documents, so remove those leaves before anchoring it to this project. Nothing was changed.',
  );
}

/** The anchor and its chained audit row, in one transaction; a compare-and-set on program_id IS NULL. */
async function writeSubmissionAnchor(submissionId: number, programId: string, reason: string, ctx: AnchorContext): Promise<void> {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const updated = (await client.query(
      `UPDATE submissions SET program_id = $1, updated_at = NOW()
        WHERE id = $2 AND organization_id = $3 AND deleted_at IS NULL AND program_id IS NULL
        RETURNING id`,
      [programId, submissionId, ctx.organizationId],
    )) as { rows?: unknown[]; rowCount?: number | null };
    if (!(updated.rowCount ?? updated.rows?.length ?? 0)) {
      throw new SubmissionError(
        'INVALID_STATE',
        'This submission was anchored to a project while this request was being checked. Nothing was changed.',
      );
    }
    await writeChainedAuditRow(client, {
      organizationId: ctx.organizationId,
      userId: ctx.userId,
      action: 'SUBMISSION_PROGRAM_ANCHORED',
      resourceType: 'submission',
      resourceId: submissionId,
      reason,
      details: { previousProgramId: null, programId, reason },
    });
    await client.query('COMMIT');
  } catch (err) {
    try { await client.query('ROLLBACK'); } catch { /* the failure below is the one to report */ }
    throw err;
  } finally {
    client.release();
  }
}

// ── Sequences ───────────────────────────────────────────────────────────────

export interface CreateSequenceInput {
  submissionId: number;
  region: string;
  sequenceNumber: string;
  type?: string;
}

/**
 * A created eCTD sequence, with what happened to the §11.10(e) record of its
 * creation carried on it.
 *
 * WO-16C #133, same defect and same reasoning as `CreatedSubmission`: the audit
 * write below was awaited at statement position and its `AuditWriteResult`
 * discarded, so a sequence created for a filing — an original, an amendment, an
 * annual report — could not be told apart from one whose creation record was
 * lost. The inserted row is returned intact with `auditTrail` added.
 */
export type CreatedSequence = EctdSequence & { auditTrail: AuditRowOutcome };

export async function createSequence(
  input: CreateSequenceInput,
  ctx: { organizationId: number; userId: number }
): Promise<CreatedSequence> {
  // Tenant ownership of the parent submission.
  const parent = await getSubmission(input.submissionId, ctx);
  // A sequence type the market does not take is refused before anything is
  // written (F19b): today, an FDA 'variation', which the packager would code
  // as an amendment to the original application. Judged on the region the
  // caller names AND the submission's own region, so naming another region
  // does not get one past. The reason is the market verdict's.
  const refused = sequenceTypeRefusal(input.region, input.type) ?? sequenceTypeRefusal(parent.primaryRegion, input.type);
  if (refused) throw new SubmissionError('VALIDATION', refused);
  const [row] = await db
    .insert(ectdSequences)
    .values({
      submissionId: input.submissionId,
      region: input.region,
      sequenceNumber: input.sequenceNumber,
      type: input.type ?? 'original',
      status: 'draft',
      organizationId: ctx.organizationId,
      createdBy: ctx.userId,
    })
    .returning();
  // Part 11 §11.10(e). The INSERT above is committed before this runs; a failed
  // audit write never deletes the sequence (a filing's sequence numbering is
  // regulatory state — removing a created sequence to make its log row's absence
  // tidy would be the worse lie). The caller is handed the outcome instead.
  const auditTrail = await recordAuditRow({
    organizationId: ctx.organizationId,
    userId: ctx.userId,
    action: 'SEQUENCE_CREATED',
    resourceType: 'ectd_sequence',
    resourceId: row.id,
    details: { submissionId: input.submissionId, region: input.region, sequenceNumber: input.sequenceNumber },
  });
  return { ...(row as EctdSequence), auditTrail };
}

export async function listSequences(
  submissionId: number,
  ctx: { organizationId: number }
): Promise<EctdSequence[]> {
  await getSubmission(submissionId, ctx);
  const rows = await db
    .select()
    .from(ectdSequences)
    .where(
      and(
        eq(ectdSequences.submissionId, submissionId),
        eq(ectdSequences.organizationId, ctx.organizationId),
        isNull(ectdSequences.deletedAt)
      )
    )
    .orderBy(ectdSequences.sequenceNumber);
  return rows as EctdSequence[];
}

export async function getSequence(id: number, ctx: { organizationId: number }): Promise<EctdSequence> {
  const [row] = await db
    .select()
    .from(ectdSequences)
    .where(and(eq(ectdSequences.id, id), eq(ectdSequences.organizationId, ctx.organizationId), isNull(ectdSequences.deletedAt)))
    .limit(1);
  if (!row) throw new SubmissionError('NOT_FOUND', 'Sequence not found for this organization.');
  return row as EctdSequence;
}

/**
 * A sequence whose status was moved by the generic (non-governed) transition,
 * with what happened to the §11.10(e) record of that move carried on it.
 *
 * WO-16C #133. The audit write below was awaited at statement position and its
 * `AuditWriteResult` discarded, so POST
 * /api/submissions/sequences/:seqId/transition answered 200 with the moved
 * sequence whether or not the row recording who moved it — and from what — was
 * written. Note the contrast one section down: the
 * governed transitions (`frozen`, `dispatched`, and transmit) do not use this
 * path at all; their audit row is written by `applySequenceChangeWithAudit` in
 * the same transaction as the state change and a failure rolls the state change
 * back. That guarantee is deliberately NOT extended here — this transition is
 * reversible (`assembling` ⇄ `draft`, `validated` ⇄ `assembling`) and internal,
 * so its rule is the repository's default: the action stands and the caller is
 * told.
 */
export type TransitionedSequence = EctdSequence & { auditTrail: AuditRowOutcome };

/** Transition a sequence's status, enforcing the pure transition rules + audit. */
export async function transitionSequence(
  id: number,
  toStatus: string,
  ctx: { organizationId: number; userId: number }
): Promise<TransitionedSequence> {
  const seq = await getSequence(id, ctx);
  if (GOVERNED_TRANSITIONS.has(toStatus)) {
    throw new SubmissionError(
      'GOVERNED_REQUIRED',
      `Transition to ${toStatus} is irreversible and must go through the governed e-signature flow (POST /api/c2c/actions sign), not this endpoint.`
    );
  }
  if (!canTransitionSequence(seq.status, toStatus)) {
    throw new SubmissionError('INVALID_STATE', `Cannot transition sequence from ${seq.status} to ${toStatus}.`);
  }
  // Validated is a claim about the content, so it is made only after the
  // validation it names has run and found no error (QA 2026-10-08, j6).
  const validation = toStatus === 'validated' ? await validateForValidatedStatus(seq, ctx) : null;
  const frozenAt = toStatus === 'frozen' ? new Date() : undefined;
  /* Same compare-and-set as the governed twin: `seq.status` was read above and
     canTransitionSequence was evaluated against it, so the write must apply only
     while the row still holds that value. Without the predicate two concurrent
     callers both passed the check and both wrote, and the second overwrote a
     transition it never saw. */
  const [row] = await db
    .update(ectdSequences)
    .set({
      status: toStatus,
      updatedAt: new Date(),
      ...(frozenAt ? { frozenAt } : {}),
      // The recorded verdict travels with the status: 'passed' when the
      // validation above cleared it, and cleared again when the sequence
      // leaves Validated for an earlier stage.
      ...(validation ? { validationStatus: 'passed' } : seq.status === 'validated' ? { validationStatus: null } : {}),
    })
    .where(
      and(
        eq(ectdSequences.id, id),
        eq(ectdSequences.organizationId, ctx.organizationId),
        eq(ectdSequences.status, seq.status),
      ),
    )
    .returning();
  if (!row) {
    throw new SubmissionError(
      'INVALID_STATE',
      `Sequence ${id} is no longer in state '${seq.status}' — it changed while this transition was being applied. Re-read the sequence and retry if the transition still applies.`,
    );
  }
  // Part 11 §11.10(e). The UPDATE above is committed; the status is not moved
  // back when this write fails. `SEQUENCE_FROZEN` appears in the action below
  // only because it is the action name for a `frozen` target — `frozen` is in
  // GOVERNED_TRANSITIONS and was already refused at the top of this function, so
  // the branch this reaches in practice is `SEQUENCE_TRANSITIONED`.
  const auditTrail = await recordAuditRow({
    organizationId: ctx.organizationId,
    userId: ctx.userId,
    action: toStatus === 'frozen' ? 'SEQUENCE_FROZEN' : 'SEQUENCE_TRANSITIONED',
    resourceType: 'ectd_sequence',
    resourceId: id,
    details: { from: seq.status, to: toStatus, ...(validation ? { validation } : {}) },
  });
  return { ...(row as EctdSequence), auditTrail };
}

/**
 * Run the sequence's deterministic validation — the dispatch-readiness checks
 * over its canonical leaves, the same findings the Validation tab shows — and
 * refuse Validated while any of them is an error. Returns the counts recorded
 * with the transition.
 *
 * QA 2026-10-08 (j6, finding 2): Validated was a free label. A sequence moved
 * to it with no validation run and validation_status NULL, while the Dispatch
 * tab told the user a sequence must be Validated before it can be frozen.
 *
 * The leaf manifest is read before and after the checks: a leaf written while
 * they ran is content they did not judge, so the move is refused rather than
 * recorded as validated. (A leaf written after the move reverts it — see
 * lockSequenceForLeafWrite.) Warnings do not block: they are the region's
 * informative findings, as they are for dispatch. Freeze and dispatch keep
 * their own gates; this one decides only what Validated may claim.
 *
 * P-22 (product decision 2026-10-08): approval gates the release, not the
 * technical validation. A leaf whose document is not yet approved is a warning
 * here (DOCUMENT_NOT_APPROVED, `blocksRelease`), so a publisher validates
 * while final approvals are collected; its count is recorded with the move,
 * and freeze, dispatch and transmit refuse the sequence until it is zero.
 */
async function validateForValidatedStatus(
  seq: EctdSequence,
  ctx: { organizationId: number },
): Promise<{ errors: number; warnings: number; notYetApproved: number; leafCount: number }> {
  const before = await sequenceLeafManifestDigest(asQueryable(pool), seq.id, ctx.organizationId);
  const { assessSequenceDispatchReadiness } = await import('../ectd/assess-dispatch-readiness');
  const a = await assessSequenceDispatchReadiness({ sequenceId: seq.id, organizationId: ctx.organizationId });
  const errors = a.readiness.findings.filter((f) => f.severity === 'error');
  if (errors.length > 0) {
    const shown = errors
      .slice(0, 5)
      .map((f) => (f.sectionCode ? `${f.sectionCode}: ${f.message}` : f.message))
      .join(' ');
    throw new SubmissionError(
      'VALIDATION_FAILED',
      `Sequence ${seq.sequenceNumber} was not marked Validated: its validation found ${errors.length} ` +
        `${errors.length === 1 ? 'error' : 'errors'}. ${shown}${errors.length > 5 ? ` (and ${errors.length - 5} more in the Validation tab)` : ''}`,
    );
  }
  const after = await sequenceLeafManifestDigest(asQueryable(pool), seq.id, ctx.organizationId);
  if (before !== after) {
    throw new SubmissionError(
      'INVALID_STATE',
      `Sequence ${seq.sequenceNumber}'s leaves changed while it was being validated, so it was not marked Validated. Validate it again.`,
    );
  }
  return { errors: 0, warnings: a.readiness.warnings, notYetApproved: a.readiness.releaseBlockers, leafCount: a.leafCount };
}

// ── Governed freeze / dispatch (the SUBMIT step of assemble→submit→transmit) ──
//
// `frozen` and `dispatched` are irreversible and outward-facing, so the generic
// transitionSequence() above refuses them. These appliers are the ONLY path that
// can produce those states, and each enforces — atomically — BOTH governance
// gates, so neither can be bypassed:
//   1. a Part 11 e-signature: a recorded `sign` governed action on THIS exact
//      sequence target, by THIS actor (proves a human authorized it); and
//   2. the deterministic dispatch gate: server-computed validation errors + open
//      Shadow Review criticals (proves the dossier is actually clear).
// The actual transmission to the agency gateway stays separate, behind the
// governed transmit_submission tool.

/** The governed transitions a sequence signature can authorize — one act each. */
export type GovernedSequenceStep = 'freeze' | 'dispatch' | 'transmit';

const STEP_AUDIT_ACTION: Record<GovernedSequenceStep, string> = {
  freeze: 'SEQUENCE_FROZEN',
  dispatch: 'SEQUENCE_DISPATCHED',
  transmit: 'ECTD_TRANSMITTED',
};

/**
 * What a sequence signature may declare it authorizes: one of the governed
 * steps, the Shadow Review waiver (P-34, ectd/shadow-review-waiver.ts), or the
 * closing of one critical Shadow Review finding (P-35,
 * ectd/shadow-finding-disposition.ts). Gate 1 verifies, spends and voids them
 * alike. Neither is a step: STEP_AUDIT_ACTION and the release intent
 * (sequence-release-signature.ts) stay the three steps' alone, so neither
 * signature freezes, dispatches, transmits or releases anything.
 */
export type SequenceSignatureIntent =
  | GovernedSequenceStep
  | typeof SHADOW_WAIVER_INTENT
  | typeof SHADOW_FINDING_DISPOSITION_INTENT;

/** How a sentence names the act a signature was given for. */
const INTENT_LABEL: Record<SequenceSignatureIntent, string> = {
  freeze: 'freeze',
  dispatch: 'dispatch',
  transmit: 'transmit',
  [SHADOW_WAIVER_INTENT]: 'Shadow Review waiver',
  [SHADOW_FINDING_DISPOSITION_INTENT]: 'Shadow Review finding disposition',
};

/**
 * The meanings an intent narrows Gate 1 to, beyond requiresIndependence. A
 * waiver (P-34) and a finding disposition (P-35) are decisions the signer
 * approves or answers for: responsibility or approval, never review or release.
 * Freeze, dispatch and transmit are approval or release steps
 * (RELEASE_ACT_MEANINGS). Until 2026-10-19 they had no entry here, so a
 * signature declaring "review", or no meaning at all, authorized them.
 */
const INTENT_MEANING_REFUSAL: Partial<Record<SequenceSignatureIntent, (meaning: unknown) => string | null>> = {
  freeze: (m) => releaseActMeaningRefusal(m, INTENT_LABEL.freeze),
  dispatch: (m) => releaseActMeaningRefusal(m, INTENT_LABEL.dispatch),
  transmit: (m) => releaseActMeaningRefusal(m, INTENT_LABEL.transmit),
  [SHADOW_WAIVER_INTENT]: shadowWaiverMeaningRefusal,
  [SHADOW_FINDING_DISPOSITION_INTENT]: shadowFindingDispositionMeaningRefusal,
};

/** Why a signature's payload does not authorize this particular request, or null (P-35: which finding, closed how). */
type SignaturePayloadRefusal = (payload: Record<string, unknown> | null) => string | null;

/**
 * Why a recorded governed `sign` action does not authorize `step` on `target`
 * for this actor, or null when it does. Four things are checked, and each used
 * to be missing:
 *   - the action exists, on this exact target, by this actor, executed;
 *   - its declared intent is this step (11.50: the meaning of the signature).
 *     One `sign` used to authorize freeze, dispatch and transmit alike;
 *   - it has not already been spent on a governed transition (a replay of the
 *     freeze-time actionId used to dispatch and transmit too);
 *   - the sequence's leaf manifest still hashes to the digest bound at signing
 *     (11.70). The digest was persisted and never consulted, so a leaf edited
 *     after signing was frozen under a signature applied to different bytes.
 */
async function governedSignatureRefusal(
  signatureActionId: string,
  target: string,
  ctx: { organizationId: number; userId: number },
  step: SequenceSignatureIntent,
): Promise<string | null> {
  return (await governedSignatureVerdict(signatureActionId, target, ctx, step)).refusal;
}

/**
 * governedSignatureRefusal, plus the leaf-manifest digest the signature binds
 * when it does authorize the step. 2026-09-23 (W5/D7, round-2 skeptic): the
 * governed freeze/dispatch re-derives that digest under the sequence row lock
 * and refuses when it moved, so the verdict is bound to what is frozen, not
 * only to what was there when Gate 1 ran.
 */
async function governedSignatureVerdict(
  signatureActionId: string,
  target: string,
  ctx: { organizationId: number; userId: number },
  step: SequenceSignatureIntent,
  payloadRefusal?: SignaturePayloadRefusal,
): Promise<
  | { refusal: string; boundDigest: null }
  | { refusal: null; boundDigest: string; signatureId: number | null; meaning: unknown }
> {
  const refuse = (refusal: string) => ({ refusal, boundDigest: null }) as const;
  const action = await db.execute(sql`
    SELECT id, payload FROM c2c_ana_actions
    WHERE id = ${signatureActionId}
      AND org_id = ${ctx.organizationId}
      AND command = 'sign'
      AND target = ${target}
      AND state = 'executed'
      AND proposed_by = ${ctx.userId}
    LIMIT 1
  `);
  const row = ((action as { rows?: Array<{ payload?: unknown }> }).rows ?? [])[0];
  if (!row) return refuse('no executed sign action on this sequence by this actor');

  const payload = typeof row.payload === 'string' ? safeJson(row.payload) : (row.payload as Record<string, unknown> | null);
  const intent = typeof payload?.intent === 'string' ? payload.intent : null;
  if (intent !== step) {
    return refuse(`the sign action declares intent '${intent ?? 'none'}', not '${step}'; sign this step with its own meaning`);
  }

  // Freeze, dispatch and transmit are approval and release acts, never an
  // author attesting authorship. The sign route skips separation of duties
  // for an authorship meaning (requiresIndependence — correct for a document
  // author signing as author), so a signature declaring one was never checked
  // for independence. Accepting it here let the sequence's creator choose
  // "Authorship" in the signing dialog and release their own submission, and
  // the release resolver then counted that signature as the §11.70 release.
  // Refused at the step itself, so it holds whichever client signed it.
  if (!requiresIndependence('sign', payload?.meaning)) {
    return refuse(
      `the signature declares the meaning '${String(payload?.meaning)}'; ${INTENT_LABEL[step]} is an approval or release step, ` +
        'so it must be signed with an approval, responsibility or release meaning by someone other than the ' +
        'sequence\'s creator',
    );
  }
  // A waiver of Shadow Review (P-34) and the closing of a critical finding
  // (P-35) are decisions the signer approves or answers for.
  const intentMeaning = INTENT_MEANING_REFUSAL[step]?.(payload?.meaning) ?? null;
  if (intentMeaning) return refuse(intentMeaning);
  // What the signature names must be what is asked: a disposition signature
  // names one finding and one disposition (P-35).
  const notThisRequest = payloadRefusal?.(payload ?? null) ?? null;
  if (notThisRequest) return refuse(notThisRequest);

  // Spent by a performed step, or void because the step it was given for was
  // refused (P-23, voidRefusedStepSignature). The void is also on the signature
  // row (checked below); this ledger read holds even where that write failed.
  const spentBy = await signatureSpentBy(signatureActionId, target, ctx.organizationId);
  if (spentBy === SIGNATURE_VOIDED_ACTION) {
    return refuse(
      `this signature was given for a ${INTENT_LABEL[step]} the server refused, so it is void; sign again for a new attempt`,
    );
  }
  if (spentBy !== null) {
    return refuse('this sign action already authorized a governed transition; each step needs its own signature');
  }

  /* The withdrawal columns are selected, not just the binding ones. A governed
     revocation (persistGovernedSignatureRevocation) marks a signature out of
     force by setting superseded_by / is_valid=false / verification_status, and
     deliberately leaves bound_payload_digest, binding_basis and
     signature_manifest byte-identical — §11.70 requires the superseded
     signature be retained unaltered. It also writes a NEW c2c_ana_actions row
     rather than touching the original `sign` row, so every earlier check in this
     function still matches a revoked signature: the sign action is still
     'executed' by the same actor, the declared intent is unchanged, the
     spent-check filters different actions, and the leaf-manifest digest still
     agrees because revocation does not alter content.

     Reading only the binding columns therefore could not distinguish a live
     signature from a withdrawn one, and revocation — the product's own §11.70
     mechanism for taking an authorization back — had no effect on freeze or
     transmit. (Dispatch was covered, because its Gate 2 release-signature check
     does apply this predicate.) */
  const esig = await db.execute(sql`
    SELECT id, bound_payload_digest, binding_basis, superseded_by, is_valid, verification_status
      FROM electronic_signatures
    WHERE organization_id = ${ctx.organizationId}
      AND signed_target = ${target}
      AND (signature_manifest::jsonb ->> 'actionId') = ${signatureActionId}
    LIMIT 1
  `);
  const sig = ((esig as unknown as {
    rows?: Array<{
      id: unknown;
      bound_payload_digest: string | null;
      binding_basis: string | null;
      superseded_by: unknown;
      is_valid: unknown;
      verification_status: unknown;
    }>;
  }).rows ?? [])[0];
  if (!sig) return refuse('no electronic signature record is bound to this sign action');
  if (String(sig.verification_status ?? '') === VOIDED_VERIFICATION_STATUS) {
    return refuse(
      `this signature was given for a ${INTENT_LABEL[step]} the server refused, so it is void; sign again for a new attempt`,
    );
  }
  if (isSignatureWithdrawn(sig)) {
    return refuse('the electronic signature authorizing this step has been revoked; obtain a new signature');
  }
  if (sig.binding_basis !== BINDING_BASIS.ECTD_SEQUENCE_LEAF_MANIFEST || !sig.bound_payload_digest) {
    return refuse('the signature is not bound to this sequence\'s leaf manifest; re-sign the sequence');
  }
  const current = await deriveGovernedTargetBinding(
    { query: (text: string, params?: unknown[]) => pool.query(text, params) as Promise<{ rows: any[] }> },
    target,
    ctx.organizationId,
  );
  if (current.digest !== sig.bound_payload_digest) {
    return refuse('the sequence changed after it was signed (leaf manifest digest differs); re-sign the current content');
  }
  const signatureId = Number(sig.id);
  return {
    refusal: null,
    boundDigest: sig.bound_payload_digest,
    signatureId: Number.isFinite(signatureId) && signatureId > 0 ? signatureId : null,
    meaning: payload?.meaning,
  };
}

function safeJson(text: string): Record<string, unknown> | null {
  try { return JSON.parse(text) as Record<string, unknown>; } catch { return null; }
}

/** The audit action that records a signature voided by a refused step (P-23). */
const SIGNATURE_VOIDED_ACTION = 'GOVERNED_SIGNATURE_VOIDED';

/**
 * The audit action that spent this sign action on this sequence — a performed
 * freeze, dispatch or transmit, a recorded Shadow Review waiver (P-34), a
 * closed critical finding (P-35), or the void a refused one recorded — or null
 * when nothing has. Each signature serves one act.
 */
async function signatureSpentBy(signatureActionId: string, target: string, organizationId: number, client?: PoolClient): Promise<string | null> {
  const sequenceId = target.slice(target.indexOf(':') + 1);
  const query = sql`
    SELECT action FROM audit_logs
    WHERE tenant_id = ${organizationId}
      AND table_name = 'ectd_sequence'
      AND record_id = ${sequenceId}
      AND action IN ('SEQUENCE_FROZEN', 'SEQUENCE_DISPATCHED', 'ECTD_TRANSMITTED', ${SHADOW_REVIEW_WAIVED_ACTION},
                     ${SHADOW_FINDING_DISPOSITIONED_ACTION}, ${SIGNATURE_VOIDED_ACTION})
      AND (new_values::jsonb ->> 'signatureActionId') = ${signatureActionId}
    LIMIT 1
  `;
  const spent = client ? await drizzle(client).execute(query) : await db.execute(query);
  const row = ((spent as { rows?: Array<{ action?: unknown }> }).rows ?? [])[0];
  return row ? String(row.action ?? '') : null;
}

/** What became of the signature a refused governed step was given. */
type SignatureVoidOutcome = 'voided' | 'not-voidable' | 'failed';

/**
 * P-23 (docs/LAUNCH_DEFINITION_OF_DONE.md, 2026-10-08): a signature collected
 * for a freeze, dispatch or transmit that the server then refuses is void. It
 * cannot be reused later when the gate clears.
 *
 * QA 2026-10-08 (j6) recorded a freeze signature for a freeze the server
 * refused at its dispatch gate. The single-use check read only the audit row a
 * PERFORMED step writes, and a refused step writes none, so that signature —
 * given while the gate refused — stayed able to freeze the sequence once the
 * gate cleared, at a time and on a state its signer never saw.
 *
 * Only the caller's own executed `sign` on this sequence that declares this
 * step is voided. A signature someone else gave, or one given for another
 * step, is refused by Gate 1 and left alone: naming a colleague's signature
 * must not be a way to cancel it. One that a performed step already spent, or
 * that is already void, is left as it is.
 *
 * Two independent records, each enough on its own for Gate 1 to refuse the
 * signature again: the signature row is taken out of force
 * (voidSignatureForRefusedAct, the row every reader checks through
 * isSignatureWithdrawn), and a chained GOVERNED_SIGNATURE_VOIDED audit row
 * names it, the step and the refusal (signatureSpentBy). The audit row is
 * written also when the signature-row write failed, so a void survives the
 * loss of either. A void that reached neither is 'failed' and is logged.
 * Never throws: the refusal is the answer the caller gives either way.
 */
async function voidRefusedStepSignature(
  signatureActionId: string,
  sequenceId: number,
  ctx: { organizationId: number; userId: number },
  step: SequenceSignatureIntent,
  refusal: string,
): Promise<SignatureVoidOutcome> {
  const target = `ectd-sequence:${sequenceId}`;
  try {
    const action = await db.execute(sql`
      SELECT payload FROM c2c_ana_actions
      WHERE id = ${signatureActionId}
        AND org_id = ${ctx.organizationId}
        AND command = 'sign'
        AND target = ${target}
        AND state = 'executed'
        AND proposed_by = ${ctx.userId}
      LIMIT 1
    `);
    const row = ((action as { rows?: Array<{ payload?: unknown }> }).rows ?? [])[0];
    if (!row) return 'not-voidable';
    const payload = typeof row.payload === 'string' ? safeJson(row.payload) : (row.payload as Record<string, unknown> | null);
    if (payload?.intent !== step) return 'not-voidable';
    if ((await signatureSpentBy(signatureActionId, target, ctx.organizationId)) !== null) return 'not-voidable';
  } catch (err) {
    logger.error('A refused governed step could not read the signature it was given, so it was not voided', {
      sequenceId, step, signatureActionId, organizationId: ctx.organizationId,
      err: err instanceof Error ? err.message : String(err),
    });
    return 'failed';
  }

  let signatureId: number | null = null;
  let signatureRowFailed = false;
  try {
    signatureId = await voidSignatureForRefusedAct(asQueryable(pool), {
      orgId: ctx.organizationId, target, actionId: signatureActionId, occurredAt: new Date(),
    });
  } catch (err) {
    signatureRowFailed = true;
    logger.error('A refused governed step could not void its signature row', {
      sequenceId, step, signatureActionId, organizationId: ctx.organizationId,
      err: err instanceof Error ? err.message : String(err),
    });
  }
  // No live signature row and no failure: nothing was persisted for this action,
  // or it is already out of force. Gate 1 refuses it either way.
  if (signatureId === null && !signatureRowFailed) return 'not-voidable';

  const audit = await recordAuditRow({
    organizationId: ctx.organizationId,
    userId: ctx.userId,
    action: SIGNATURE_VOIDED_ACTION,
    resourceType: 'ectd_sequence',
    resourceId: sequenceId,
    details: { signatureActionId, signatureId, signatureRowVoided: signatureId !== null, step, refusal },
  });
  if (signatureId !== null || audit.persisted) return 'voided';
  logger.error('A refused governed step voided its signature nowhere', { sequenceId, step, signatureActionId, organizationId: ctx.organizationId });
  return 'failed';
}

/** What the signer is told about the signature a refused step was given. */
function voidedSignatureSentence(outcome: SignatureVoidOutcome, step: SequenceSignatureIntent): string {
  if (outcome === 'voided') return ` The signature given for this ${INTENT_LABEL[step]} is now void; sign again for a new attempt.`;
  if (outcome === 'failed') {
    return ` The signature given for this ${INTENT_LABEL[step]} could not be marked void right now; do not reuse it, sign again for a new attempt.`;
  }
  return '';
}

/**
 * Run a governed step; when it is refused, void the signature it was given
 * (voidRefusedStepSignature) and say so in the refusal. `voidable(err)` decides
 * whether a failure is a refusal of the act — false only where the act may have
 * happened (a transmit that reached the gateway).
 */
async function voidingSignatureOnRefusal<T>(
  run: () => Promise<T>,
  sig: { signatureActionId: string; sequenceId: number; ctx: { organizationId: number; userId: number }; step: SequenceSignatureIntent },
  voidable: (err: unknown) => boolean | Promise<boolean> = () => true,
): Promise<T> {
  try {
    return await run();
  } catch (err) {
    if (!(await voidable(err))) throw err;
    const refusal = err instanceof Error ? err.message : String(err);
    const outcome = await voidRefusedStepSignature(sig.signatureActionId, sig.sequenceId, sig.ctx, sig.step, refusal);
    const sentence = voidedSignatureSentence(outcome, sig.step);
    if (!sentence) throw err;
    if (err instanceof SubmissionError) throw new SubmissionError(err.code, `${err.message}${sentence}`);
    if (err instanceof Error) err.message = `${err.message}${sentence}`;
    throw err;
  }
}


/**
 * Apply a sequence state change and its hash-chained audit row in ONE
 * transaction. auditService.logAction swallows a persistence failure by policy
 * (an audit outage must not break a general user action); for a Part 11
 * governed transition the claim is the opposite — no freeze, dispatch or
 * transmission without its audit row — so the row is written with
 * writeChainedAuditRow on the same client and a failure rolls the state
 * change back.
 */
async function applySequenceChangeWithAudit(
  update: {
    text: string;
    params: unknown[];
    /**
     * What zero affected rows MEANS for this caller. When the UPDATE carries a
     * compare-and-set predicate, zero rows is a LOST RACE (the state moved after
     * it was read), not a missing sequence, and reporting "not found" for it
     * would send the operator looking for the wrong problem.
     */
    noRowsRefusal?: string;
    /**
     * Runs inside the transaction, after BEGIN and before the UPDATE, on the
     * same client — where a caller takes its row locks and re-checks what it
     * judged, so the UPDATE applies only to the state that was judged
     * (2026-09-23, W5/D7, round-2 skeptic). A throw rolls everything back.
     */
    underLock?: (client: PoolClient) => Promise<void>;
  },
  audit: { organizationId: number; userId: number; action: string; resourceId: number; details: Record<string, unknown> },
): Promise<void> {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    if (update.underLock) await update.underLock(client);
    const res = (await client.query(update.text, update.params)) as { rowCount?: number | null };
    if (!res.rowCount) {
      throw update.noRowsRefusal
        ? new SubmissionError('INVALID_STATE', update.noRowsRefusal)
        : new SubmissionError('NOT_FOUND', 'Sequence not found for this organization.');
    }
    await writeChainedAuditRow(client, {
      organizationId: audit.organizationId,
      userId: audit.userId,
      action: audit.action,
      resourceType: 'ectd_sequence',
      resourceId: audit.resourceId,
      details: audit.details,
    });
    await client.query('COMMIT');
  } catch (err) {
    try { await client.query('ROLLBACK'); } catch { /* the failure below is the one to report */ }
    throw err;
  } finally {
    client.release();
  }
}

/** The one query surface the governed-transition checks run on: the pool, or the transaction's client. */
type SequenceQueryable = { query: (text: string, params?: unknown[]) => Promise<{ rows: any[] }> };

const asQueryable = (q: Pick<PoolClient, 'query'> | typeof pool): SequenceQueryable => ({
  query: (text, params) => (q.query as (t: string, p?: unknown[]) => Promise<{ rows: any[] }>)(text, params),
});

/**
 * The leaf-manifest digest of a sequence — the Gate-1 binding
 * (deriveGovernedTargetBinding), read on `q` so it sees that client's view.
 */
async function sequenceLeafManifestDigest(q: SequenceQueryable, id: number, organizationId: number): Promise<string | null> {
  return (await deriveGovernedTargetBinding(q, `ectd-sequence:${id}`, organizationId)).digest;
}

/** The columns of a submission_leaves row that decide its lifecycle key. */
type LifecycleKeyLeaf = {
  section_code: string | null;
  lifecycle_op: string | null;
  document_table: string | null;
  document_id: number | null;
  document_uuid: string | null;
};

/**
 * The lifecycle keys two sequences' leaves share, described for a refusal, or
 * null when neither can move the other (2026-09-23, W5/D7, residual repair).
 *
 * A leaf's key is its section plus its document reference — the inputs of the
 * leaf file name the lifecycle operator keys by (leafFileName over
 * leafSourceKey, passed in so this uses the one canonical key). The same
 * document in the same section is a shared key. A withdrawal row that names no
 * document has no key of its own: package-from-core binds it by SECTION, so it
 * shares the whole section with every leaf the other sequence files there.
 * A non-withdrawal leaf that names no document has no key at all (it cannot be
 * packaged, and the package gate refuses it).
 */
function sharedLifecycleKeys(
  mine: LifecycleKeyLeaf[],
  theirs: LifecycleKeyLeaf[],
  leafSourceKey: (table: string | null | undefined, id: number | null | undefined, uuid?: string | null) => string,
): string | null {
  const sectionOf = (l: LifecycleKeyLeaf) => String(l.section_code ?? '').trim().toLowerCase();
  const documentOf = (l: LifecycleKeyLeaf): string | null =>
    l.document_table && String(l.document_table).trim() && (l.document_id || l.document_uuid)
      ? leafSourceKey(String(l.document_table).trim(), l.document_id, l.document_uuid).toLowerCase()
      : null;
  const bindsBySection = (l: LifecycleKeyLeaf) =>
    documentOf(l) === null && String(l.lifecycle_op ?? '').trim().toLowerCase() === 'delete';
  const found: string[] = [];
  const sections = new Set(mine.map(sectionOf));
  for (const section of [...sections].sort()) {
    const a = mine.filter((l) => sectionOf(l) === section);
    const b = theirs.filter((l) => sectionOf(l) === section);
    if (b.length === 0) continue;
    const label = String(a[0].section_code ?? '').trim();
    if (a.some(bindsBySection) || b.some(bindsBySection)) {
      found.push(`${label}: a withdrawal there names no document, so it binds by section`);
      continue;
    }
    const theirDocs = new Set(b.map(documentOf).filter((k): k is string => k !== null));
    const same = [...new Set(a.map(documentOf).filter((k): k is string => k !== null && theirDocs.has(k)))].sort();
    if (same.length > 0) found.push(`${label}: document ${same.join(', ')}`);
  }
  return found.length > 0 ? found.join('; ') : null;
}

/**
 * Why this sequence may not be frozen/dispatched because of another sequence of
 * the same submission it shares a section with, or null.
 *
 * 2026-09-23 (W5/D7, round-2 skeptic). The package gate judges lifecycle binding
 * against the FILED inventory: the sequences numbered BELOW this one whose
 * dispatch_status is sent or acknowledged (loadLatestPriorManifestBySubmission).
 * A verdict holds at transmit only if that inventory cannot move after the lock,
 * and a sequence judged against it must not be filed behind one it never saw.
 * So one rule, two directions:
 *   - LOWER: a lower sequence is frozen/dispatched and not yet sent. Sending it
 *     changes what this one binds to, so wait until it is sent.
 *   - HIGHER: a higher sequence is frozen or dispatched, WHATEVER its dispatch
 *     status. This one can no longer be filed ahead of it; its leaves belong in
 *     a new sequence numbered after it.
 *
 * 2026-09-23 (W5/D7, round-2 skeptic, second pass). The higher direction first
 * refused only while the higher sequence was unsent, and told the operator to
 * "send it first, then freeze this one". Doing that let this one freeze,
 * dispatch and transmit judged against the inventory BELOW it only — the
 * loader never reads a higher number — so its withdrawal bound to a leaf the
 * higher sequence had already replaced, and it shipped with no blockers. A
 * lower sequence can never be filed correctly after a higher one in a shared
 * section; the remedy is a new number, and the refusal now holds once the
 * higher one is sent.
 *
 * The one exception is a pair the governed path can no longer produce: this
 * sequence is already frozen (the dispatch step) and the higher one is only
 * frozen, not dispatched and not filed — both locked before this rule existed.
 * Refusing both directions there deadlocked the pair ('frozen' has no way out
 * but 'dispatched'). The lower one dispatches: the higher one is still refused
 * by the lower direction until this one is sent, and is then judged at its own
 * dispatch against an inventory that includes this one. When the higher one of
 * such a pair is already dispatched or filed, this one stays refused — it may be
 * sent at any time, and this one would then transmit a lifecycle judged without
 * it.
 *
 * DEPENDENCY — a shared LIFECYCLE KEY, not a shared section (see
 * sharedLifecycleKeys). The lifecycle operator identifies a leaf by section +
 * file name, and the file name is derived from the leaf's document reference
 * (leafFileName over leafSourceKey), so a leaf of this sequence — a declared
 * replace/append/delete, or a declared 'new' whose operation the operator
 * derives from what is on file — is moved only by another sequence's leaf for
 * the SAME document in the SAME section. The one binding that is not by
 * document is a withdrawal row that names no document: package-from-core binds
 * it by section, so a sequence with one depends on every leaf the other files
 * in that section, in both directions. Sections compare case- and
 * whitespace-insensitively and document keys case-insensitively: a spelling
 * difference must not hide a dependency.
 *
 * 2026-09-23 (W5/D7, residual repair). This used to be "shares a section".
 * Every IND sequence carries its own Form FDA 1571 (m1.1) and cover letter
 * (m1.2) (ind-lifecycle-persistence withTransmittalPair), so for an IND that
 * narrowing never applied: filing became strictly serial per submission, and
 * because the higher direction holds once the higher sequence is sent, an
 * urgent safety report numbered 0002 filed ahead of a protocol amendment 0001
 * stranded 0001 for good — although 0001's package was all 'new', with no
 * modified-file, and nothing 0002 filed could move it. Two sequences that each
 * file their own document in a section now move independently.
 *
 * REGIONS. Not scoped by region, on purpose: the prior-state loader it guards
 * reads every region of the submission, so an EMA 0000 being sent moves an FDA
 * 0001's inventory exactly as an FDA 0000 would. Scoping only this rule would
 * reopen the defect across regions. The refusal names the other sequence's
 * region so the operator can see why.
 *
 * Reported as its own refusal, not as a package defect: the leaves are not
 * wrong, and the only remedy is ordering (issue 3 of the same review).
 */
async function filingOrderRefusal(
  q: SequenceQueryable,
  seq: { id: number; submissionId: number; sequenceNumber: string; status: string },
  organizationId: number,
  step: GovernedSequenceStep,
): Promise<string | null> {
  const res = await q.query(
    `SELECT o.id, o.sequence_number, o.status, o.dispatch_status, o.region
       FROM ectd_sequences o
      WHERE o.submission_id = $1 AND o.organization_id = $2 AND o.deleted_at IS NULL
        AND o.id <> $3 AND o.sequence_number <> $4
        AND o.status IN ('frozen', 'dispatched')
      ORDER BY o.sequence_number`,
    [seq.submissionId, organizationId, seq.id, seq.sequenceNumber],
  );
  type Other = { id: number; sequence_number: string; status: string; dispatch_status: string | null; region: string | null; shared_sections: string };
  const locked = (res.rows ?? []) as Other[];
  if (locked.length === 0) return null;
  const leafRes = await q.query(
    `SELECT sequence_id, section_code, lifecycle_op, document_table, document_id, document_uuid
       FROM submission_leaves
      WHERE organization_id = $1 AND deleted_at IS NULL AND sequence_id = ANY($2::int[])`,
    [organizationId, [seq.id, ...locked.map((r) => Number(r.id))]],
  );
  const leavesOf = new Map<number, LifecycleKeyLeaf[]>();
  for (const l of (leafRes.rows ?? []) as Array<LifecycleKeyLeaf & { sequence_id: number }>) {
    const id = Number(l.sequence_id);
    leavesOf.set(id, [...(leavesOf.get(id) ?? []), l]);
  }
  const { leafSourceKey } = await import('../ectd/leaf-source-resolver');
  const mine = leavesOf.get(seq.id) ?? [];
  const dependent: Other[] = [];
  for (const r of locked) {
    const shared = sharedLifecycleKeys(mine, leavesOf.get(Number(r.id)) ?? [], leafSourceKey);
    if (shared) dependent.push({ ...r, shared_sections: shared });
  }
  const isFiled = (r: Other) => isFiledDispatchStatus(r.dispatch_status);
  // Zero-padded fixed-width sequence numbers: lexical order is filing order,
  // the same assumption the prior-sequence loaders rely on.
  const lower = dependent.filter((r) => String(r.sequence_number) < seq.sequenceNumber && !isFiled(r));
  // The pre-rule frozen pair (see above): only a higher one that is dispatched
  // or filed holds back an already-frozen lower one.
  const legacyFrozenPair = (r: Other) => seq.status === 'frozen' && r.status === 'frozen' && !isFiled(r);
  const higher = dependent.filter((r) => String(r.sequence_number) > seq.sequenceNumber && !legacyFrozenPair(r));
  const state = (r: Other) =>
    `${r.status}, dispatch status '${r.dispatch_status ?? 'none'}', region '${r.region ?? 'none'}'`;
  if (lower.length > 0) {
    const first = lower[0];
    const others = lower.slice(1).map((r) => r.sequence_number);
    return (
      `Refusing to ${step}: sequence ${first.sequence_number} is not yet filed; ${step} this one after it is sent` +
      `${others.length > 0 ? ` (also not yet filed: ${others.join(', ')})` : ''}. ` +
      `It is ${state(first)}, and it files the same lifecycle key — ${first.shared_sections} — where this sequence's lifecycle ` +
      'operations are bound against what is on file — sending it changes that, so a verdict taken now would not hold at transmit. ' +
      'This is a filing-order constraint, not a defect in this sequence\'s leaves.'
    );
  }
  if (higher.length > 0) {
    const last = higher[higher.length - 1];
    const first = higher[0];
    const filed = isFiled(first);
    return (
      `Refusing to ${step}: sequence ${first.sequence_number} is ${filed ? 'already filed' : `${first.status} and not yet filed`} ` +
      `(${state(first)}) and files the same lifecycle key — ${first.shared_sections} — where this sequence's lifecycle operations bind. ` +
      'This sequence can no longer be filed ahead of it: it is judged only against the sequences numbered below it, ' +
      (filed
        ? `so its lifecycle operations would bind to what ${first.sequence_number} has already changed. `
        : `and ${first.sequence_number}'s lifecycle operations were judged without this one on file, so whichever is sent ` +
          'second would transmit a lifecycle judged against the wrong inventory. ') +
      `Place these leaves in a new sequence numbered after ${last.sequence_number}, where they are judged against what it files. ` +
      'This is a filing-order constraint, not a defect in this sequence\'s leaves.'
    );
  }
  return null;
}

/**
 * Refuse a governed step when the package this sequence would transmit is not
 * transmittable — the rule transmitSequence applies (assembledTransmitBlockers),
 * run on the same assembly before the sequence is locked.
 *
 * Returns the leaf-manifest digest the assembly ran against, read BEFORE it
 * started (2026-09-23, W5/D7, round-2 skeptic): the caller compares it with the
 * digest under the sequence row lock, so a leaf placed or removed while the
 * package was assembling is refused instead of frozen unjudged.
 */
async function assertSequencePackageable(
  id: number,
  ctx: { organizationId: number; userId: number },
  step: GovernedSequenceStep,
): Promise<string | null> {
  const assembledAgainst = await sequenceLeafManifestDigest(asQueryable(pool), id, ctx.organizationId);
  const { assembleSequence, assembledTransmitBlockers } = await import('../ectd/assemble-from-core');
  let assembled: Awaited<ReturnType<typeof assembleSequence>>;
  try {
    // A dry run (package-identity.ts): the blockers do not depend on the
    // agency identifiers, so it names none and carries the one dry-run
    // placeholder. It produces no package — the bundle is discarded below on
    // every path, and nothing of it is stored or sent (P-27, 2026-10-08).
    assembled = await assembleSequence({
      sequenceId: id,
      organizationId: ctx.organizationId,
      userId: ctx.userId,
      dryRun: true,
    });
  } catch (err) {
    throw new SubmissionError(
      'DISPATCH_BLOCKED',
      `Refusing to ${step}: the sequence does not assemble into a package (${err instanceof Error ? err.message : String(err)}). ` +
        'Fix it while the leaves can still be changed.',
    );
  }
  try {
    const gaps = assembledTransmitBlockers(assembled);
    if (gaps.length > 0) {
      throw new SubmissionError(
        'DISPATCH_BLOCKED',
        `Refusing to ${step}: ${gaps.join('; ')}. Transmit would refuse this package, and once the sequence is ` +
          `${step === 'freeze' ? 'frozen' : 'dispatched'} its leaves can no longer be changed.`,
      );
    }
  } finally {
    await assembled.cleanup();
  }
  return assembledAgainst;
}

/**
 * Gates 2 and 3 of a governed freeze or dispatch: everything but the
 * signature. Throws DISPATCH_BLOCKED with the refusal; returns the assessment
 * and the leaf-manifest digest the package gate assembled against.
 *
 * Gate 2 — deterministic dispatch gate (server-computed inputs; tamper-proof),
 * composed for the step (`verdictFor` picks which verdict). Freeze takes every
 * gate except the REQUIREMENT for a §11.70 release signature: that control is
 * the transmit re-check, a release signature comes from a signed package
 * orchestrator run, and requiring one to freeze inverted the order the product
 * works in — freeze, then build and sign the release. A tampered signature
 * still blocks a freeze, and dispatch is unchanged. See assess-dispatch-
 * readiness → composeDispatchGatesForStep.
 *
 * Gate 3 — the package this sequence would transmit (2026-09-23, W5/D7).
 * Transmit refuses a package that leaves out a placed leaf, carries an
 * unapproved document, or cannot materialize a source (assembledTransmit-
 * Blockers). Readiness does not assemble, so those refusals used to surface
 * only at transmit — after freeze had made the leaves immutable and dispatch
 * had removed every way back: a signed sequence that could never be sent.
 * The same assembly and the same rule run here, while the author can still act.
 *
 * 2026-09-23 (W5/D7, round-2 skeptic): the filing-order rule runs FIRST, so a
 * sequence waiting on a lower one is told to wait rather than told its leaves
 * cannot be packaged — the lifecycle binding it would fail on is judged
 * against an inventory that is about to change.
 *
 * Extracted 2026-10-08 (QA j6, finding 1) so precheckGovernedStep asks these
 * exact gates BEFORE a signature is taken: the client signed first and asked
 * the gate second, so a refused freeze left an executed approval signature.
 */
async function governedContentGates(
  seq: EctdSequence,
  ctx: { organizationId: number; userId: number },
  step: 'freeze' | 'dispatch',
  verdictFor: (a: DispatchReadinessAssessment) => { cleared: boolean; blockers: string[] },
): Promise<{ assessment: DispatchReadinessAssessment; assembledAgainst: string | null }> {
  const toStatus = step === 'freeze' ? 'frozen' : 'dispatched';
  const { assessSequenceDispatchReadiness } = await import('../ectd/assess-dispatch-readiness');
  const assessment = await assessSequenceDispatchReadiness({ sequenceId: seq.id, organizationId: ctx.organizationId });
  const stepGate = verdictFor(assessment);
  if (!stepGate.cleared) {
    throw new SubmissionError(
      'DISPATCH_BLOCKED',
      `Dispatch gate blocks ${toStatus}: ${stepGate.blockers.join(' ')}`
    );
  }
  const orderRefusal = await filingOrderRefusal(asQueryable(pool), seq, ctx.organizationId, step);
  if (orderRefusal) throw new SubmissionError('DISPATCH_BLOCKED', orderRefusal);
  const assembledAgainst = await assertSequencePackageable(seq.id, ctx, step);
  return { assessment, assembledAgainst };
}

/** What a precheck of a governed step answers. `cleared: false` carries the
 *  server's refusal, in the words the step itself would refuse with. */
export interface GovernedStepPrecheck {
  step: SequenceSignatureIntent;
  cleared: boolean;
  refusal: string | null;
  /** Transmit only: where it would go and whether that gateway can send. */
  transmit?: SequenceTransmitReadiness;
  /** Shadow Review waiver only (P-34): whether one is offered, and the failed run it would cite. */
  shadowWaiver?: ShadowReviewWaivability;
  /** Finding disposition only (P-35): how the named finding may be closed now, and the later run 'fixed' rests on. */
  shadowFindingDisposition?: ShadowFindingDisposability;
}

/** What a precheck may name beyond the step: a transmit's destination, a disposition's finding. */
export interface GovernedPrecheckOptions {
  environment?: 'staging' | 'production';
  applicationId?: string;
  /** Finding disposition (P-35): the finding to close, and how. */
  findingId?: number;
  disposition?: string;
}

/** The disposition's own rule (P-35), the one dispositionShadowFinding applies. */
async function precheckShadowFindingDisposition(
  seq: EctdSequence,
  ctx: { organizationId: number },
  opts: GovernedPrecheckOptions,
): Promise<GovernedStepPrecheck> {
  const step = SHADOW_FINDING_DISPOSITION_INTENT;
  const { findingId, disposition } = opts;
  if (typeof findingId !== 'number' || !isShadowFindingDisposition(disposition)) {
    return { step, cleared: false, refusal: 'Name the finding and how it is closed (accepted or fixed); nothing was checked.' };
  }
  const shadowFindingDisposition = await shadowFindingDisposable(asQueryable(pool), {
    sequenceId: seq.id, organizationId: ctx.organizationId, findingId,
  });
  const refusal = shadowFindingDispositionRefusal(shadowFindingDisposition, disposition);
  return { step, cleared: refusal === null, refusal, shadowFindingDisposition };
}

/**
 * Would this governed step be refused for a reason other than its signature?
 * Runs the step's own gates — for freeze and dispatch, governedContentGates
 * (the dispatch verdict as it will stand once the dispatch signature is
 * recorded, since that signature is the one about to be taken); for transmit,
 * sequenceTransmitReadiness — and changes nothing a governed step depends on.
 * The package gate's assembly writes its own ECTD_ASSEMBLED audit row, as it
 * does at freeze.
 *
 * QA 2026-10-08 (j6, finding 1): the Sequences row opened the e-signature with
 * no gate shown, the client posted the signature, and only then did the freeze
 * refuse — an executed approval signature for a freeze that did not happen.
 * The client now asks here first and signs only on `cleared`. The step still
 * runs every gate again itself; this is advice, never authority.
 */
export async function precheckGovernedStep(
  id: number,
  step: SequenceSignatureIntent,
  ctx: { organizationId: number; userId: number },
  opts: GovernedPrecheckOptions = {},
): Promise<GovernedStepPrecheck> {
  if (step === 'transmit') {
    const transmit = await sequenceTransmitReadiness(id, ctx, opts.environment, opts.applicationId);
    return { step, cleared: transmit.refusal === null, refusal: transmit.refusal, transmit };
  }
  const seq = await getSequence(id, ctx);
  // The waiver's own rule (P-34), the one waiveShadowReview applies.
  if (step === SHADOW_WAIVER_INTENT) {
    const shadowWaiver = await shadowReviewWaivable(asQueryable(pool), { sequenceId: seq.id, organizationId: ctx.organizationId });
    return { step, cleared: shadowWaiver.eligible, refusal: shadowWaiver.eligible ? null : shadowWaiver.reason, shadowWaiver };
  }
  if (step === SHADOW_FINDING_DISPOSITION_INTENT) return precheckShadowFindingDisposition(seq, ctx, opts);
  const toStatus = step === 'freeze' ? 'frozen' : 'dispatched';
  if (!canTransitionSequence(seq.status, toStatus)) {
    return { step, cleared: false, refusal: `Cannot transition sequence from ${seq.status} to ${toStatus}.` };
  }
  try {
    await governedContentGates(seq, ctx, step, (a) => (step === 'freeze' ? a.freezeGate : a.dispatchGateOnSigning));
    return { step, cleared: true, refusal: null };
  } catch (err) {
    if (err instanceof SubmissionError && err.code === 'DISPATCH_BLOCKED') {
      return { step, cleared: false, refusal: err.message };
    }
    throw err;
  }
}

/**
 * The Shadow Review waiver a governed step went forward on (P-34): what its
 * §11.10(e) row names when the presence gate cleared because of a waiver, so a
 * freeze, dispatch or transmit made without an AI review says under which
 * signature, and on which failed run. Null when a completed review cleared it.
 */
function waiverReliedOn(a: Partial<Pick<DispatchReadinessAssessment, 'shadowReviewRunCount' | 'shadowReviewWaiver'>>): Record<string, unknown> | null {
  const w = a.shadowReviewWaiver;
  if (a.shadowReviewRunCount !== 0 || w?.state !== 'active') return null;
  return {
    signatureActionId: w.signatureActionId ?? null,
    signatureId: w.signatureId ?? null,
    waiverRunId: w.waiverRunId ?? null,
    failedRunId: w.failedRunId ?? null,
    failureCode: w.failureCode ?? null,
  };
}

/** `{ shadowReviewWaiver }` for an audit row's details, or nothing. */
function withWaiverReliedOn(a: Parameters<typeof waiverReliedOn>[0]): { shadowReviewWaiver?: Record<string, unknown> } {
  const w = waiverReliedOn(a);
  return w ? { shadowReviewWaiver: w } : {};
}

/**
 * Under the transition lock, on the transaction's client: does what the
 * Shadow Review half of the verdict relied on still stand? The assessment ran
 * seconds earlier, unlocked; a revocation in that window must not freeze or
 * dispatch over it. A waiver it relied on must still be active (P-34), and no
 * critical finding may block that it counted as closed (P-35: a closure stands
 * only while its signature is in force). The reason, or null.
 */
async function shadowReviewRefusalUnderLock(
  q: SequenceQueryable,
  a: Partial<Pick<DispatchReadinessAssessment, 'shadowReviewRunCount' | 'shadowReviewWaiver' | 'unacknowledgedShadowCriticals'>>,
  scope: { sequenceId: number; organizationId: number },
  step: string,
): Promise<string | null> {
  const since = `Since this ${step} was checked`;
  const criticals = await criticalsStandingOpen(q, scope);
  if (criticals.count > Number(a.unacknowledgedShadowCriticals ?? 0)) {
    const why = criticals.reopened.map(reopenedCriticalSentence).join(' ');
    return `${since}, a critical Shadow Review finding blocks dispatch again. ${why}`.trim();
  }
  if (!waiverReliedOn(a)) return null;
  const presence = evaluateShadowPresenceWithWaiver(
    await completedShadowReviewRuns(q, scope),
    await resolveShadowReviewWaiver(q, scope),
  );
  return presence.cleared ? null : `${since}, the Shadow Review waiver it relied on no longer stands. ${presence.blockers.join(' ')}`;
}

async function applyGovernedSequenceTransition(
  id: number,
  toStatus: 'frozen' | 'dispatched',
  ctx: { organizationId: number; userId: number },
  signatureActionId: string
): Promise<EctdSequence> {
  const seq = await getSequence(id, ctx);
  if (!canTransitionSequence(seq.status, toStatus)) {
    throw new SubmissionError('INVALID_STATE', `Cannot transition sequence from ${seq.status} to ${toStatus}.`);
  }

  // Gate 1 — Part 11 e-signature must govern THIS sequence, for THIS step,
  // signed by THIS actor, unspent, and bound to the current leaf manifest.
  const target = `ectd-sequence:${id}`;
  const step: GovernedSequenceStep = toStatus === 'frozen' ? 'freeze' : 'dispatch';
  const verdict = await governedSignatureVerdict(signatureActionId, target, ctx, step);
  if (verdict.refusal !== null) {
    throw new SubmissionError(
      'GOVERNED_REQUIRED',
      `A valid e-signature is required: sign ${target} via POST /api/c2c/actions/sign with intent '${step}', then pass its actionId. Refused: ${verdict.refusal}.`
    );
  }

  // Gates 2 and 3 — see governedContentGates. Freeze reads the freeze verdict;
  // dispatch reads `gate`, with the dispatch signature above now on record.
  const { assessment, assembledAgainst } = await governedContentGates(
    seq,
    ctx,
    step === 'freeze' ? 'freeze' : 'dispatch',
    (a) => (toStatus === 'frozen' ? a.freezeGate : a.gate),
  );

  // The state change and its chained audit row commit together, or neither.
  // 'dispatched' queues the sequence for transmit (dispatch_status pending);
  // it is not yet sent.
  await applySequenceChangeWithAudit(
    {
      /* 2026-09-23 (W5/D7, round-2 skeptic): bind the gates to what is frozen.
         The CAS below is on status only, and the gate above assembles for
         seconds while the sequence is still unlocked — a leaf placed or removed
         in that window was frozen without having been judged, and no gate
         re-checked it. Under the lock:
           - the submission row, so governed transitions of one submission
             serialize and the filing-order rule cannot be passed by two
             sequences at once;
           - the sequence row — the lock upsertLeaf/removeLeaf take for their
             writes (lockSequenceForLeafWrite), so no leaf write through them
             interleaves. 2026-09-23 (residual repair): ingestion's
             classifyDocument, the last direct submission_leaves writer outside
             the seed scripts, now places through upsertLeaf too, so every
             product leaf write takes this lock (the second-pass note that it
             did not is superseded);
           - the leaf-manifest digest (the Gate-1 binding) must still be the one
             the package gate assembled against AND the one the signature binds;
           - the filing-order rule is re-read. */
      underLock: async (client) => {
        await client.query(`SELECT id FROM submissions WHERE id = $1 AND organization_id = $2 FOR UPDATE`, [
          seq.submissionId,
          ctx.organizationId,
        ]);
        await client.query(
          `SELECT id FROM ectd_sequences WHERE id = $1 AND organization_id = $2 AND deleted_at IS NULL FOR UPDATE`,
          [id, ctx.organizationId],
        );
        const q = asQueryable(client);
        const now = await sequenceLeafManifestDigest(q, id, ctx.organizationId);
        if (now === null || now !== assembledAgainst || now !== verdict.boundDigest) {
          throw new SubmissionError(
            'INVALID_STATE',
            `Sequence ${id}'s leaves changed while this ${step} was being checked (the leaf manifest no longer matches ` +
              'the one the package gate assembled and the signature binds). Nothing was changed; re-check the leaves and sign again.',
          );
        }
        const lockedOrderRefusal = await filingOrderRefusal(q, seq, ctx.organizationId, step);
        if (lockedOrderRefusal) throw new SubmissionError('DISPATCH_BLOCKED', lockedOrderRefusal);
        const shadowRefusal = await shadowReviewRefusalUnderLock(q, assessment, { sequenceId: id, organizationId: ctx.organizationId }, step);
        if (shadowRefusal) throw new SubmissionError('DISPATCH_BLOCKED', shadowRefusal);
      },
      /* COMPARE-AND-SET on the status this transition was authorized against.
         `seq.status` was read at the top of this function, and everything since —
         three queries in governedSignatureRefusal, deriveGovernedTargetBinding,
         and the whole dispatch readiness assessment including an external
         validator call — is a window in which another author can move the same
         sequence. Without the predicate both callers' UPDATEs applied, each
         spending its own signature and each writing a §11.10(e) row, so the
         ledger recorded two irreversible transitions from a state only one of
         them actually observed. */
      text: toStatus === 'frozen'
        ? `UPDATE ectd_sequences SET status = $1, updated_at = NOW(), frozen_at = NOW() WHERE id = $2 AND organization_id = $3 AND deleted_at IS NULL AND status = $4`
        : `UPDATE ectd_sequences SET status = $1, updated_at = NOW(), dispatch_status = 'pending' WHERE id = $2 AND organization_id = $3 AND deleted_at IS NULL AND status = $4`,
      params: [toStatus, id, ctx.organizationId, seq.status],
      noRowsRefusal:
        `Sequence ${id} is no longer in state '${seq.status}' — it changed while this ${step} was being authorized. ` +
        `Re-check the sequence and sign again if the transition still applies.`,
    },
    {
      organizationId: ctx.organizationId,
      userId: ctx.userId,
      action: STEP_AUDIT_ACTION[step],
      resourceId: id,
      details: {
        from: seq.status,
        to: toStatus,
        signatureActionId,
        validationErrors: assessment.validationErrors,
        unacknowledgedShadowCriticals: assessment.unacknowledgedShadowCriticals,
        // P-34: the waiver this step went forward on, when no review had completed.
        ...withWaiverReliedOn(assessment),
      },
    },
  );
  logger.info('Governed sequence transition applied', { id, toStatus, organizationId: ctx.organizationId });
  return getSequence(id, ctx);
}

/** Freeze a validated sequence. Governed: requires e-signature + a clear dispatch gate.
 *  A refused freeze voids the signature it was given (P-23). */
export function freezeSequence(
  id: number,
  ctx: { organizationId: number; userId: number },
  signatureActionId: string
): Promise<EctdSequence> {
  return voidingSignatureOnRefusal(
    () => applyGovernedSequenceTransition(id, 'frozen', ctx, signatureActionId),
    { signatureActionId, sequenceId: id, ctx, step: 'freeze' },
  );
}

/** Mark a frozen sequence dispatched. Governed: requires e-signature + a clear gate.
 *  This records intent; actual transmission stays behind transmit_submission.
 *  A refused dispatch voids the signature it was given (P-23). */
export function dispatchSequence(
  id: number,
  ctx: { organizationId: number; userId: number },
  signatureActionId: string
): Promise<EctdSequence> {
  return voidingSignatureOnRefusal(
    () => applyGovernedSequenceTransition(id, 'dispatched', ctx, signatureActionId),
    { signatureActionId, sequenceId: id, ctx, step: 'dispatch' },
  );
}

// ── The Shadow Review waiver (P-34) ──────────────────────────────────────────

/**
 * Record a signed Shadow Review waiver (P-34, docs/LAUNCH_DEFINITION_OF_DONE.md,
 * 2026-10-15): the sequence's newest Shadow Review run failed because every AI
 * provider failed or was overloaded, and a person with signing authority who
 * did not author the sequence signs that it may proceed unreviewed. The rules
 * are ectd/shadow-review-waiver.ts's; this is the act, and its one door is
 * POST /api/submissions/sequences/:seqId/shadow-review/waive (no AnA tool).
 *
 * Gate 1 is the governed steps' own (governedSignatureVerdict with intent
 * 'shadow-waiver': this actor, this sequence, responsibility or approval,
 * unspent, bound to the current leaf manifest). Separation of duties is checked
 * again here, so it holds whichever client signed. Eligibility is re-asked
 * under the sequence row lock — the lock leaf writes take — with the leaf
 * manifest the signature binds. The 'waived' row and its chained
 * SHADOW_REVIEW_WAIVED audit row commit together or not at all, and that audit
 * row spends the signature. The signature's own reason is the waiver's reason.
 * A refused waive voids the signature it was given (P-23).
 */
export function waiveShadowReview(
  input: { sequenceId: number; signatureActionId: string; failedRunId: number },
  ctx: { organizationId: number; userId: number },
): Promise<ShadowReviewWaiverRecord> {
  return voidingSignatureOnRefusal(
    () => applyShadowReviewWaiver(input, ctx),
    { signatureActionId: input.signatureActionId, sequenceId: input.sequenceId, ctx, step: SHADOW_WAIVER_INTENT },
  );
}

/**
 * Separation of duties for a decision signed on the sequence — the Shadow
 * Review waiver (P-34), the closing of a critical finding (P-35) — as a
 * refusal: the sequence's creator never waives its review or closes what the
 * review found. Checked at the act, so it holds whichever client signed.
 */
async function independentSignerRefusal(
  target: string,
  ctx: { organizationId: number; userId: number },
  meaning: unknown,
): Promise<SubmissionError | null> {
  try {
    await assertSignerIsNotAuthor(target, ctx.organizationId, ctx.userId, { command: 'sign', meaning });
    return null;
  } catch (err) {
    if (err instanceof SeparationOfDutiesError) return new SubmissionError('FORBIDDEN', err.message);
    if (err instanceof SeparationOfDutiesAuthorUnresolvedError) return new SubmissionError('INVALID_STATE', err.message);
    throw err;
  }
}

/**
 * Inside a sequence act's transaction: take the sequence row lock — the lock
 * leaf writes take — re-ask the act's own rule on the transaction's client, and
 * refuse when the leaves are no longer the ones the signature binds. A throw
 * rolls the act back.
 */
async function recheckUnderSequenceLock(
  client: PoolClient,
  p: { sequenceId: number; organizationId: number; boundDigest: string; act: string; recheck: (q: SequenceQueryable) => Promise<void> },
): Promise<void> {
  await client.query(
    `SELECT id FROM ectd_sequences WHERE id = $1 AND organization_id = $2 AND deleted_at IS NULL FOR UPDATE`,
    [p.sequenceId, p.organizationId],
  );
  const q = asQueryable(client);
  await p.recheck(q);
  if ((await sequenceLeafManifestDigest(q, p.sequenceId, p.organizationId)) !== p.boundDigest) {
    throw new SubmissionError(
      'INVALID_STATE',
      `Sequence ${p.sequenceId}'s leaves changed while this ${p.act} was being recorded, so the signature no longer binds them. ` +
        'Nothing was recorded; sign again over the current leaves.',
    );
  }
}

async function applyShadowReviewWaiver(
  input: { sequenceId: number; signatureActionId: string; failedRunId: number },
  ctx: { organizationId: number; userId: number },
): Promise<ShadowReviewWaiverRecord> {
  const { signatureActionId, failedRunId } = input;
  const seq = await getSequence(input.sequenceId, ctx);
  const target = `ectd-sequence:${seq.id}`;
  const verdict = await governedSignatureVerdict(signatureActionId, target, ctx, SHADOW_WAIVER_INTENT);
  if (verdict.refusal !== null) {
    throw new SubmissionError(
      'GOVERNED_REQUIRED',
      `A valid e-signature is required: sign ${target} via POST /api/c2c/actions/sign with intent '${SHADOW_WAIVER_INTENT}' ` +
        `and the meaning responsibility or approval, then pass its actionId. Refused: ${verdict.refusal}.`,
    );
  }
  const independence = await independentSignerRefusal(target, ctx, verdict.meaning);
  if (independence) throw independence;
  const offered = await shadowReviewWaivable(asQueryable(pool), { sequenceId: seq.id, organizationId: ctx.organizationId });
  const notOffered = shadowWaiverRunRefusal(offered, failedRunId);
  if (notOffered !== null) throw new SubmissionError('SHADOW_WAIVER_NOT_ELIGIBLE', notOffered);
  const failureCode = offered.failureCode;
  if (!isWaivableShadowReviewFailure(failureCode)) throw new SubmissionError('SHADOW_WAIVER_NOT_ELIGIBLE', offered.reason);

  const insert = shadowWaiverInsert({
    sequenceId: seq.id, organizationId: ctx.organizationId, signerId: ctx.userId, signatureActionId, failedRunId, failureCode,
  });
  await applySequenceChangeWithAudit(
    {
      underLock: (client) =>
        recheckUnderSequenceLock(client, {
          sequenceId: seq.id,
          organizationId: ctx.organizationId,
          boundDigest: verdict.boundDigest,
          act: 'waiver',
          recheck: async (q) => {
            const still = shadowWaiverRunRefusal(
              await shadowReviewWaivable(q, { sequenceId: seq.id, organizationId: ctx.organizationId }),
              failedRunId,
            );
            if (still !== null) throw new SubmissionError('SHADOW_WAIVER_NOT_ELIGIBLE', still);
          },
        }),
      text: insert.text,
      params: insert.params,
      noRowsRefusal: `Run #${failedRunId} is no longer a failed run of this sequence, so nothing was waived.`,
    },
    {
      organizationId: ctx.organizationId,
      userId: ctx.userId,
      action: SHADOW_REVIEW_WAIVED_ACTION,
      resourceId: seq.id,
      details: { signatureActionId, signatureId: verdict.signatureId, failedRunId, failureCode },
    },
  );
  logger.info('Shadow Review waived', { sequenceId: seq.id, failedRunId, failureCode, organizationId: ctx.organizationId });
  const waiver = await resolveShadowReviewWaiver(asQueryable(pool), { sequenceId: seq.id, organizationId: ctx.organizationId });
  return { sequenceId: seq.id, failedRunId, failureCode, signatureActionId, signatureId: verdict.signatureId, waiver };
}

// ── Closing a critical Shadow Review finding (P-35) ──────────────────────────

/**
 * Close one open critical Shadow Review finding by a Part 11 signature (P-35,
 * docs/LAUNCH_DEFINITION_OF_DONE.md, 2026-10-15): 'accepted' (the finding
 * stands and the signer accepts going forward with it) or 'fixed' (the signer
 * states what changed; offered only when a completed review ran after the
 * finding's run). The rules are ectd/shadow-finding-disposition.ts's; this is
 * the act, and its one door is
 * POST /api/submissions/sequences/:seqId/shadow-review/findings/:findingId/disposition
 * (no AnA tool).
 *
 * Gate 1 is the governed steps' own, with intent 'shadow-finding-disposition'
 * and the payload naming THIS finding and THIS disposition (a signature for
 * finding A closes neither finding B nor A another way). Separation of duties
 * is checked again here. Eligibility is re-asked under the sequence row lock
 * with the leaf manifest the signature binds. The finding's status and its
 * disposition columns, and the chained SHADOW_FINDING_DISPOSITIONED row that
 * spends the signature, commit together or not at all. The signature's own
 * reason is the disposition's reason. A refused act voids its signature (P-23).
 */
export function dispositionShadowFinding(
  input: ShadowFindingDispositionRequest & { sequenceId: number; signatureActionId: string },
  ctx: { organizationId: number; userId: number },
): Promise<ShadowFindingDispositionRecord> {
  return voidingSignatureOnRefusal(
    () => applyShadowFindingDisposition(input, ctx),
    { signatureActionId: input.signatureActionId, sequenceId: input.sequenceId, ctx, step: SHADOW_FINDING_DISPOSITION_INTENT },
  );
}

async function applyShadowFindingDisposition(
  input: ShadowFindingDispositionRequest & { sequenceId: number; signatureActionId: string },
  ctx: { organizationId: number; userId: number },
): Promise<ShadowFindingDispositionRecord> {
  const { findingId, disposition, signatureActionId } = input;
  const seq = await getSequence(input.sequenceId, ctx);
  const target = `ectd-sequence:${seq.id}`;
  const verdict = await governedSignatureVerdict(signatureActionId, target, ctx, SHADOW_FINDING_DISPOSITION_INTENT, (payload) =>
    shadowFindingDispositionPayloadRefusal(payload, { findingId, disposition }),
  );
  if (verdict.refusal !== null) {
    throw new SubmissionError(
      'GOVERNED_REQUIRED',
      `A valid e-signature is required: sign ${target} via POST /api/c2c/actions/sign with intent ` +
        `'${SHADOW_FINDING_DISPOSITION_INTENT}', the payload { findingId: ${findingId}, disposition: '${disposition}' } and the ` +
        `meaning approval or responsibility, then pass its actionId. Refused: ${verdict.refusal}.`,
    );
  }
  const independence = await independentSignerRefusal(target, ctx, verdict.meaning);
  if (independence) throw independence;
  const scope = { sequenceId: seq.id, organizationId: ctx.organizationId, findingId };
  const offered = await shadowFindingDisposable(asQueryable(pool), scope);
  const notOffered = shadowFindingDispositionRefusal(offered, disposition);
  if (notOffered !== null) throw new SubmissionError('SHADOW_FINDING_NOT_DISPOSABLE', notOffered);
  const reason = await dispositionSignatureReason(asQueryable(pool), { organizationId: ctx.organizationId, signatureActionId });
  if (reason === null) {
    throw new SubmissionError('GOVERNED_REQUIRED', 'The signature records no reason, so nothing was closed; sign again with your reason.');
  }

  const runId = Number(offered.runId);
  // Compare-and-set on what was judged: an open critical, or one whose closing
  // signature is no longer in force and so blocks again (closureStands).
  const judged = offered.judged;
  if (!judged) throw new SubmissionError('SHADOW_FINDING_NOT_DISPOSABLE', offered.reason);
  const update = shadowFindingDispositionUpdate({ ...scope, signerId: ctx.userId, disposition, signatureActionId, reason, judged });
  await applySequenceChangeWithAudit(
    {
      underLock: (client) =>
        recheckUnderSequenceLock(client, {
          sequenceId: seq.id,
          organizationId: ctx.organizationId,
          boundDigest: verdict.boundDigest,
          act: 'disposition',
          recheck: async (q) => {
            const still = shadowFindingDispositionRefusal(await shadowFindingDisposable(q, scope), disposition);
            if (still !== null) throw new SubmissionError('SHADOW_FINDING_NOT_DISPOSABLE', still);
          },
        }),
      text: update.text,
      params: update.params,
      noRowsRefusal: `Finding #${findingId} changed while this disposition was being recorded (it was closed, deleted or moved), so nothing was closed.`,
    },
    {
      organizationId: ctx.organizationId,
      userId: ctx.userId,
      action: SHADOW_FINDING_DISPOSITIONED_ACTION,
      resourceId: seq.id,
      details: { findingId, runId, disposition, signatureActionId, signatureId: verdict.signatureId },
    },
  );
  logger.info('Shadow Review finding closed by signature', { sequenceId: seq.id, findingId, runId, disposition, organizationId: ctx.organizationId });
  // The act is committed; a failed read-back is said as null, never as a refusal.
  const dispositionRecord = await readShadowFindingDisposition(asQueryable(pool), { organizationId: ctx.organizationId, findingId })
    .catch((err: unknown) => {
      logger.warn('A recorded finding disposition could not be read back', {
        sequenceId: seq.id, findingId, err: err instanceof Error ? err.message : String(err),
      });
      return null;
    });
  return { sequenceId: seq.id, findingId, runId, disposition, signatureActionId, signatureId: verdict.signatureId, dispositionRecord };
}

// ── Transmit (the TRANSMIT step — assemble → send to the agency gateway) ──────
//
// Connects a DISPATCHED sequence to the real agency gateway: it re-verifies the
// e-signature + dispatch gate, assembles the package bytes, selects the regional
// gateway, and transmits — but ONLY when the org has credentials for that
// gateway+environment (otherwise it reports `gateway_not_configured` honestly
// rather than failing). The gateway implementation persists the
// submission_transmittals record and performs the real transport (AS2 / OAuth2 /
// mTLS+HMAC). Tenant-scoped + audited.

/** Where transmitSequence sends a sequence, or why it sends it nowhere. */
export type TransmitRoute =
  | { ok: true; gwRegion: string; gwName: string }
  | { ok: false; reason: string };

/**
 * Route a submission to its agency gateway by region, client type and filing
 * type. FDA (incl. eSTAR) routes through ESG; Japan through the PMDA gateway.
 *
 * The EU splits twice. Device/IVD (mdx|ivd) register through EUDAMED. A drug or
 * biologic dossier goes to CESP only when its filing type resolves
 * (`resolveToRegistryEntry`) to a filing the one channel function,
 * `submissionChannelFor` (regulatory/registry/submittabilityCoverage.ts), routes
 * to ema:cesp — the national, MRP and DCP filings. Anything else is refused with
 * the channel named: a centralised-procedure filing (MAA, variation, renewal,
 * PSUR, ASMF) goes through the EMA eSubmission Gateway / Web Client, which the
 * platform has no connector for (DECISIONS.md row 10); a CTA through CTIS; an
 * orphan, PIP, PRIME or advice request through IRIS. A filing type that names
 * no registry filing is refused too: nothing says CESP accepts it.
 *
 * 2026-10-05 (D2 record, step g-cesp-centralised-refusal; finding 42): every
 * non-device EU dossier was routed to ema:cesp, so an e-signed centralised MAA
 * sequence would have been POSTed to CESP's /baskets. EMA has made the
 * eSubmission Gateway / Web Client mandatory for centralised-procedure eCTD
 * submissions since 2014-03-01 (basis: docs/evidence/
 * D2-ANA-DOCUMENT-INTELLIGENCE/2026-10-05-record/g-cesp-centralised-refusal-facts.md).
 */
export function transmitRouteFor(
  region: string,
  clientType: string,
  applicationType?: string | null
): TransmitRoute {
  switch (region) {
    case 'fda':
      return { ok: true, gwRegion: 'fda', gwName: 'esg' };
    case 'jp':
    case 'pmda':
      return { ok: true, gwRegion: 'pmda', gwName: 'pmda_gateway' };
    case 'eu':
    case 'ema': {
      if (clientType === 'mdx' || clientType === 'ivd') return { ok: true, gwRegion: 'ema', gwName: 'eudamed' };
      const type = typeof applicationType === 'string' ? applicationType.trim() : '';
      const entry = type ? resolveToRegistryEntry(type) : null;
      if (!entry) {
        return {
          ok: false,
          reason: `The filing type ${type ? `"${type}"` : '(none recorded)'} names no filing in the regulatory registry, so the platform cannot tell whether CESP accepts it (CESP carries national, MRP and DCP filings only; a centralised-procedure filing goes through the EMA eSubmission Gateway / Web Client). Nothing was sent.`,
        };
      }
      const notCesp = cespChannelRefusal(entry, submissionChannelFor(entry));
      if (notCesp) return { ok: false, reason: `${notCesp} Nothing was sent.` };
      return { ok: true, gwRegion: 'ema', gwName: 'cesp' };
    }
    case 'ca':
      return { ok: true, gwRegion: 'ca', gwName: 'hc_cesg' };
    case 'uk':
      return { ok: true, gwRegion: 'uk', gwName: 'mhra_gateway' };
    case 'cn':
      return { ok: true, gwRegion: 'cn', gwName: 'nmpa_gateway' };
    case 'au':
      return { ok: true, gwRegion: 'au', gwName: 'tga_ebs' };
    case 'ch':
      return { ok: true, gwRegion: 'ch', gwName: 'swissmedic_egateway' };
    case 'br':
      return { ok: true, gwRegion: 'br', gwName: 'anvisa_gateway' };
    case 'in':
      return { ok: true, gwRegion: 'in', gwName: 'cdsco_sugam' };
    case 'kr':
      return { ok: true, gwRegion: 'kr', gwName: 'mfds_dbio' };
    case 'sg':
      return { ok: true, gwRegion: 'sg', gwName: 'hsa_prism' };
    default:
      return { ok: false, reason: `No transmit gateway is mapped for region "${region}".` };
  }
}

/** The gateway pair `transmitRouteFor` names, or null when it refuses. */
export function selectGateway(
  region: string,
  clientType: string,
  applicationType?: string | null
): { gwRegion: string; gwName: string } | null {
  const route = transmitRouteFor(region, clientType, applicationType);
  return route.ok ? { gwRegion: route.gwRegion, gwName: route.gwName } : null;
}

/** Project a gateway transmit status onto the sequence's coarse dispatch_status. */
/**
 * Why a dispatched sequence must not be transmitted again, or null. The only
 * guard was status === 'dispatched', which transmit never changes, so a second
 * call — same signature — produced a second real transmittal at the agency.
 * A rejected transmission may be retried; a sent or acknowledged one may not.
 */
export const TRANSMITTING_STATUS = 'transmitting';

export function resendRefusal(dispatchStatus: string | null | undefined): string | null {
  if (dispatchStatus === TRANSMITTING_STATUS) {
    return `A transmit of this sequence is already in flight (dispatch status '${dispatchStatus}'). It is not sent again while that attempt is unresolved — confirm at the agency whether the package arrived before retrying.`;
  }
  if (dispatchStatus === 'sent' || dispatchStatus === 'acknowledged') {
    return `Sequence was already transmitted (dispatch status '${dispatchStatus}'); it is not sent again. A correction is a new sequence.`;
  }
  return null;
}

function toDispatchStatus(status: string): 'sent' | 'acknowledged' | 'rejected' {
  if (status === 'rejected' || status === 'validation_failed') return 'rejected';
  if (status === 'ack3_received' || status === 'validation_passed' || status === 'completed') return 'acknowledged';
  return 'sent';
}

export interface TransmitSequenceParams {
  sequenceId: number;
  ctx: { organizationId: number; userId: number };
  signatureActionId: string;
  /**
   * Required. This defaulted to 'production' — the exact defect
   * submission-gateways/types.ts records as the reason TransmitAuthorization
   * exists — so an omitted environment sent the package to the live agency
   * endpoint.
   */
  environment?: 'staging' | 'production';
  /**
   * The agency application number (IND/NDA/BLA). Required to transmit — an
   * absent one used to be spelled UNASSIGNED-SEQ-<id> in the backbone and on
   * the SFTP path and sent anyway. Both stay optional in the TYPE so the HTTP
   * route's optional fields still compile; transmitSequence refuses at runtime.
   */
  applicationId?: string;
  sponsorId?: string;
  /* No sponsorName: the applicant is the organisation's recorded name
     (package-identity.ts), never a value the caller supplies. QA 2026-10-08 (j6). */
}

export interface TransmitSequenceResult {
  transmitted: boolean;
  /** Set when not transmitted (e.g. 'gateway_not_configured'). */
  reason?: string;
  /**
   * What happened to the §11.10(e) row for a transmit that was NOT performed.
   *
   * WO-16C #133. Set ONLY on the `gateway_not_configured` return below, which is
   * the one audit write in this function that goes through `recordAuditRow`; it
   * was `await auditService.logAction({…})` at statement position, so the
   * `transmitted: false` answer was identical whether or not the attempt was
   * recorded anywhere. Deliberately a key of its own: the successful path's
   * `ECTD_TRANSMITTED` row is written by `applySequenceChangeWithAudit` inside
   * the same transaction as the dispatch_status update and rolls that update
   * back if it cannot be written, so it needs no field here — and because this
   * key is never set on that path, it can never be read as that row's outcome.
   */
  skipAudit?: AuditRowOutcome;
  region: string;
  gateway: string;
  transmittalId?: number;
  transmissionId?: string | null;
  status?: string;
  dispatchStatus: string;
  /**
   * Package checks the transmit guard ran that FAILED without blocking (a
   * flag-gated check not enforced here), as "name: detail". null = the guard
   * reported nothing, which is not "all passed". Set on a performed transmit.
   */
  preTransmitFailedChecks?: string[] | null;
  /** The transmit guard's warnings (e.g. evidence it could not check). */
  preTransmitWarnings?: string[] | null;
  /**
   * Set when nothing was transmitted (`transmitted: false`): whether the
   * signature given for this attempt is now void (P-23). It must not serve a
   * later attempt either way; false only when the void could not be recorded.
   */
  signatureVoided?: boolean;
}

/**
 * Claim the transmit slot with a COMPARE-AND-SET, before any bytes leave.
 *
 * `dispatch_status` is the only thing preventing a second real transmission to
 * an agency, and it used to be read at the top of transmitSequence and written
 * only AFTER the wire. Everything in between — both gates, the readiness
 * assessment, package assembly, and the AS2/SFTP transfer itself — was a window
 * in which a second caller read the same 'pending', passed the same guard, and
 * transmitted the same sequence again. The single-use signature check could not
 * catch it either: it looks for an audit row that is written after the transfer.
 *
 * Taking the claim here narrows that to a single atomic UPDATE. The predicate is
 * the value that was read, so exactly one concurrent caller wins and the loser
 * is refused with the ordinary INVALID_STATE wording.
 *
 * It is deliberately NOT inside applySequenceChangeWithAudit: that helper rolls
 * its state change back when the §11.10(e) row cannot be written, which is right
 * for freeze but wrong once a package is already at the agency — it left
 * dispatch_status at 'pending' with the bytes delivered, so the operator's retry
 * sent them a second time. The claim commits on its own and therefore survives
 * that rollback.
 */
async function claimTransmitSlot(sequenceId: number, organizationId: number, signatureActionId: string, attemptId: string): Promise<boolean> {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await setTenantContextTx(client, organizationId);
    await client.query(`SELECT id FROM ectd_sequences WHERE id = $1 AND organization_id = $2 AND deleted_at IS NULL FOR UPDATE`, [sequenceId, organizationId]);
    // A receipt may settle while this request waits for the sequence lock.
    // Read the canonical ledger in a fresh statement after acquiring it.
    if (await signatureSpentBy(signatureActionId, `ectd-sequence:${sequenceId}`, organizationId, client)) {
      throw new SubmissionError('GOVERNED_REQUIRED', 'The transmit signature was already used or voided. Sign a new transmit attempt. Nothing was transmitted.');
    }
    const res = await client.query(
      `UPDATE ectd_sequences
          SET dispatch_status = $3, transmit_signature_action_id = $4, transmit_attempt_id = $5, updated_at = NOW()
        WHERE id = $1 AND organization_id = $2 AND deleted_at IS NULL
          AND status = 'dispatched'
          AND (dispatch_status IS NULL OR dispatch_status IN ('pending', 'rejected'))
        RETURNING id`,
      [sequenceId, organizationId, TRANSMITTING_STATUS, signatureActionId, attemptId],
    );
    await client.query('COMMIT');
    return (res.rowCount ?? res.rows?.length ?? 0) > 0;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

/**
 * Release a claim taken for an attempt that failed BEFORE the wire, so a
 * packaging error does not wedge the sequence. Only ever called on the pre-wire
 * path: once gw.transmit has been entered, delivery is ambiguous and the claim
 * is deliberately left standing for a human to resolve.
 */
async function releaseTransmitSlot(sequenceId: number, organizationId: number, signatureActionId: string, attemptId: string): Promise<void> {
  await pool.query(
    `UPDATE ectd_sequences SET dispatch_status = 'pending', transmit_signature_action_id = NULL, transmit_attempt_id = NULL, updated_at = NOW()
      WHERE id = $1 AND organization_id = $2 AND dispatch_status = $3 AND transmit_signature_action_id = $4 AND transmit_attempt_id = $5`,
    [sequenceId, organizationId, TRANSMITTING_STATUS, signatureActionId, attemptId],
  );
}

/** Whether, and where, a sequence can be transmitted — read before anyone signs. */
export interface SequenceTransmitReadiness {
  sequenceStatus: string;
  dispatchStatus: string | null;
  /** The gateway transmitRouteFor names, or why it names none. */
  route: { ok: true; region: string; gateway: string } | { ok: false; reason: string };
  /** Credentials per environment: null when the route names no gateway or the
   *  check could not run (unknown is not "configured"). */
  configured: { staging: boolean | null; production: boolean | null };
  /** Protocol installation and agency UAT proof are independent of credentials. */
  transportReadiness: {
    staging: import('../../../shared/schema/gateway-transport').GatewayTransportReadiness | null;
    production: import('../../../shared/schema/gateway-transport').GatewayTransportReadiness | null;
  };
  /** The program's recorded agency application number, when one is usable. */
  recordedApplicationNumber: string | null;
  /** The organisation's recorded name, which the package names as the applicant. */
  recordedApplicant: string | null;
  /** The transmit-time dispatch gate (`gate`, every gate composed). */
  gate: { cleared: boolean; blockers: string[] };
  /** Why transmit would be refused before the wire — for `environment` when
   *  one is given, else for every environment — or null when it would not. */
  refusal: string | null;
}

/**
 * Why `typed` may not be transmitted as this filing's application number, or
 * null. P-23 (docs/LAUNCH_DEFINITION_OF_DONE.md, 2026-10-08): transmit checks a
 * typed number against the program's recorded one, as the eCTD export already
 * does (assemble-from-core.ts exportApplicationId, answered 409
 * APPLICATION_NUMBER_MISMATCH by ectd-export.ts). The record is authoritative;
 * a number it contradicts would be written into the backbone and the package
 * name and sent to the agency. A program with no usable recorded number is
 * refused before this is asked (packageIdentityRefusal, QA 2026-10-08 j6): it
 * used to accept any usable typed number, so a package went out under a number
 * no record held.
 */
export function transmitApplicationNumberRefusal(typed: string, recorded: string | null): SubmissionError | null {
  const usable = usableIdentifier('applicationNumber', typed);
  if (usable === null) {
    return new SubmissionError(
      'VALIDATION',
      `"${typed.trim()}" is not a usable application number: it must start with a letter or digit and hold only ` +
        'letters, digits, ".", "_" or "-" (up to 64). Nothing was sent.',
    );
  }
  if (recorded !== null && usable !== recorded) {
    return new SubmissionError(
      'APPLICATION_NUMBER_MISMATCH',
      `Application number "${usable}" does not match the program's recorded application number "${recorded}". ` +
        'The record is authoritative: transmit under the recorded number, or correct the program record first. Nothing was sent.',
    );
  }
  return null;
}

/** transmitApplicationNumberRefusal's sentence for a number the person typed; null when none was typed. */
function typedApplicationNumberRefusal(typed: string | undefined, recorded: string | null): string | null {
  if (typeof typed !== 'string' || !typed.trim()) return null;
  return transmitApplicationNumberRefusal(typed, recorded)?.message ?? null;
}

/**
 * The pre-signature half of transmitSequence, as a read: status, re-send rule,
 * the dispatch gate, the route, and the gateway's credentials. Same functions,
 * same order, minus Gate 1 (the signature that has not been taken yet).
 *
 * QA 2026-10-08 (j6, the blocker): a dispatched sequence had no path to a
 * package or a transmit, and the copy promised "the governed transmit path"
 * without naming it. The Dispatch tab reads this to say where the sequence
 * would go and whether that gateway can send — "not configured" is said
 * before a password is typed, never discovered after.
 */
export async function sequenceTransmitReadiness(
  sequenceId: number,
  ctx: { organizationId: number; userId: number },
  environment?: 'staging' | 'production',
  /** The number the person typed, when they have: judged against the record
   *  here, before anyone signs (P-23), by the rule transmit applies. */
  applicationId?: string,
): Promise<SequenceTransmitReadiness> {
  const seq = await getSequence(sequenceId, ctx);
  const submission = await getSubmission(seq.submissionId, ctx);
  const routed = transmitRouteFor(seq.region, submission.clientType, submission.applicationType || seq.type);
  const route: SequenceTransmitReadiness['route'] = routed.ok
    ? { ok: true, region: routed.gwRegion, gateway: routed.gwName }
    : { ok: false, reason: routed.reason };

  const configured: SequenceTransmitReadiness['configured'] = { staging: null, production: null };
  const transportReadiness: SequenceTransmitReadiness['transportReadiness'] = { staging: null, production: null };
  if (routed.ok) {
    const { getGateway, gatewayTransportReadiness } = await import('../submission-gateways/index');
    // transmitRouteFor returns valid Region/GatewayName values, as transmitSequence relies on.
    const gw = getGateway(routed.gwRegion as Parameters<typeof getGateway>[0], routed.gwName as Parameters<typeof getGateway>[1]);
    for (const env of ['staging', 'production'] as const) {
      try {
        configured[env] = await gw.isConfigured(ctx.organizationId, env);
      } catch {
        configured[env] = null;
      }
      transportReadiness[env] = await gatewayTransportReadiness(
        routed.gwRegion as Parameters<typeof gatewayTransportReadiness>[0],
        routed.gwName as Parameters<typeof gatewayTransportReadiness>[1],
        env,
      ).catch(() => null);
    }
  }

  const { assessSequenceDispatchReadiness } = await import('../ectd/assess-dispatch-readiness');
  const assessment = await assessSequenceDispatchReadiness({ sequenceId, organizationId: ctx.organizationId });
  const gate = { cleared: assessment.gate.cleared, blockers: [...assessment.gate.blockers] };

  // The applicant and the application the package would name, from the record
  // (package-identity.ts); with either missing transmit refuses, and says so here.
  const identity = await readRecordedPackageIdentity(pool, ctx.organizationId, submission.programId);
  const recordedApplicationNumber = identity.applicationNumber;
  const identityRefusal = packageIdentityRefusal(identity, 'Nothing can be sent until it is recorded.')?.message ?? null;
  const typedNumberRefusal = identityRefusal ?? typedApplicationNumberRefusal(applicationId, recordedApplicationNumber);

  const gatewayRefusal = (): string | null => {
    if (!route.ok) return route.reason;
    const envs = environment ? [environment] : (['staging', 'production'] as const);
    if (envs.every((e) => transportReadiness[e]?.implementation === 'unavailable')) {
      return transportReadiness[envs[0]]?.reason ?? 'This agency transport is unavailable. Nothing can be transmitted.';
    }
    const unusable = envs.filter((e) => configured[e] !== true);
    if (unusable.length < envs.length) return null;
    const unknown = unusable.some((e) => configured[e] === null);
    return unknown
      ? `Whether this sequence's agency gateway is configured for ${envs.join(' or ')} could not be checked, so nothing can be sent until it can.`
      : `This sequence's agency gateway has no ${envs.join(' or ')} credentials configured for this organization, so nothing can be sent. Nothing was signed or transmitted.`;
  };
  const refusal =
    seq.status !== 'dispatched'
      ? `Sequence must be dispatched before transmit (current: ${seq.status}).`
      : resendRefusal(seq.dispatchStatus) ??
        (!gate.cleared ? `Dispatch gate blocks transmit: ${gate.blockers.join(' ')}` : null) ??
        typedNumberRefusal ??
        gatewayRefusal();

  return {
    sequenceStatus: seq.status,
    dispatchStatus: seq.dispatchStatus ?? null,
    route,
    configured,
    transportReadiness,
    recordedApplicationNumber,
    recordedApplicant: identity.applicantName,
    gate,
    refusal,
  };
}

/**
 * Transmit a dispatched sequence to its regional agency gateway. Governed:
 * requires a valid e-signature on the sequence target AND a clear dispatch gate.
 * Real transmission only occurs when the gateway is configured for the org.
 *
 * P-23: an attempt that sends nothing voids the signature it was given — a
 * refusal before the gateway, a refusal the gateway guard made before the wire
 * (refusedBeforeWire), and `transmitted: false`. A failure once the package
 * may have reached the agency voids nothing: that signature is the one of
 * record for whatever the agency holds. The request's own shape (environment,
 * a usable application number) is checked before anything is read; a request
 * missing them is malformed, not refused, and voids nothing.
 */
export async function transmitSequence(params: TransmitSequenceParams): Promise<TransmitSequenceResult> {
  const { sequenceId, ctx, signatureActionId } = params;
  if (params.environment !== 'staging' && params.environment !== 'production') {
    throw new SubmissionError('VALIDATION', 'Transmit requires an explicit environment: staging or production.');
  }
  const environment = params.environment;
  const typed = typeof params.applicationId === 'string' ? params.applicationId.trim() : '';
  if (!typed || /^UNASSIGNED/i.test(typed)) {
    throw new SubmissionError(
      'VALIDATION',
      'Transmit requires the agency application number; a sequence with none recorded is assembled for inspection only, never sent.',
    );
  }
  const unusable = transmitApplicationNumberRefusal(typed, null);
  if (unusable) throw unusable;
  const applicationId = usableIdentifier('applicationNumber', typed) ?? typed;

  const attempt = { reachedGateway: false };
  const result = await voidingSignatureOnRefusal(
    () => transmitDispatchedSequence(params, { environment, applicationId }, attempt),
    { signatureActionId, sequenceId, ctx, step: 'transmit' },
    async (err) => {
      if (!attempt.reachedGateway) return true;
      const { refusedBeforeWire } = await import('../submission-gateways/index');
      return refusedBeforeWire(err);
    },
  );
  if (result.transmitted) return result;
  const voided = await voidRefusedStepSignature(
    signatureActionId, sequenceId, ctx, 'transmit', `Not transmitted: ${result.reason ?? 'the gateway did not send it'}.`,
  );
  return { ...result, signatureVoided: voided === 'voided' };
}

/** transmitSequence past the request's shape: every gate, then the gateway.
 *  `attempt.reachedGateway` is set as the package is handed to it. */
async function transmitDispatchedSequence(
  params: TransmitSequenceParams,
  checked: { environment: 'staging' | 'production'; applicationId: string },
  attempt: { reachedGateway: boolean },
): Promise<TransmitSequenceResult> {
  const { sequenceId, ctx, signatureActionId } = params;
  const { environment, applicationId } = checked;
  const seq = await getSequence(sequenceId, ctx);
  if (seq.status !== 'dispatched') {
    throw new SubmissionError('INVALID_STATE', `Sequence must be dispatched before transmit (current: ${seq.status}).`);
  }
  const resend = resendRefusal(seq.dispatchStatus);
  if (resend) throw new SubmissionError('INVALID_STATE', resend);

  // The typed application number against the program's record (P-23), as the
  // eCTD export judges it. The submission is read here, once, for the route too.
  const submission = await getSubmission(seq.submissionId, ctx);
  // The package names its applicant and its application from the record, or it
  // is not sent (package-identity.ts, QA 2026-10-08 j6).
  const identity = await readRecordedPackageIdentity(pool, ctx.organizationId, submission.programId);
  const missingIdentity = packageIdentityRefusal(identity, 'Nothing was sent.');
  if (missingIdentity) throw new SubmissionError('PACKAGE_IDENTITY_MISSING', missingIdentity.message);
  const numberRefusal = transmitApplicationNumberRefusal(applicationId, identity.applicationNumber);
  if (numberRefusal) throw numberRefusal;
  const applicantName = identity.applicantName as string;

  // Gate 1 — Part 11 e-signature on this sequence, for transmit, by this actor.
  const target = `ectd-sequence:${sequenceId}`;
  const refusal = await governedSignatureRefusal(signatureActionId, target, ctx, 'transmit');
  if (refusal !== null) {
    throw new SubmissionError(
      'GOVERNED_REQUIRED',
      `A valid e-signature is required: sign ${target} via POST /api/c2c/actions/sign with intent 'transmit', then pass its actionId. Refused: ${refusal}.`
    );
  }

  // Gate 2 — deterministic dispatch gate must still be clear (defense in depth).
  const { assessSequenceDispatchReadiness } = await import('../ectd/assess-dispatch-readiness');
  const assessment = await assessSequenceDispatchReadiness({ sequenceId, organizationId: ctx.organizationId });
  if (!assessment.gate.cleared) {
    throw new SubmissionError('DISPATCH_BLOCKED', `Dispatch gate blocks transmit: ${assessment.gate.blockers.join(' ')}`);
  }

  // Route by region, client type and filing type (EU device/IVD → EUDAMED; an
  // EU dossier → CESP only for a national/MRP/DCP filing — see transmitRouteFor).
  // The submission's applicationType names the filing; seq.type is the
  // lifecycle (original|amendment|…) and is read only when it is empty.
  const route = transmitRouteFor(seq.region, submission.clientType, submission.applicationType || seq.type);
  if (!route.ok) {
    throw new SubmissionError('VALIDATION', route.reason);
  }

  const { getGateway, preTransmitFindings } = await import('../submission-gateways/index');
  // gwRegion and gwName are always valid Region/GatewayName values returned by transmitRouteFor
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const gw = getGateway(route.gwRegion as any, route.gwName as any);

  // Honest: only transmit when the org has credentials for this gateway+env.
  if (!(await gw.isConfigured(ctx.organizationId, environment))) {
    // Part 11 §11.10(e) for an attempt that changed nothing: no package was
    // assembled, no bytes left the server, and no row was updated, so there is
    // nothing here to revert and the refusal itself is already reported to the
    // caller in `reason`. This audit row is nonetheless the only place the
    // attempt is persisted at all, so its loss is reported too, in `skipAudit`,
    // rather than leaving "we never tried" and "we tried and could not record
    // it" as the same response (WO-16C #133).
    const skipAudit = await recordAuditRow({
      organizationId: ctx.organizationId,
      userId: ctx.userId,
      action: 'ECTD_TRANSMIT_SKIPPED',
      resourceType: 'ectd_sequence',
      resourceId: sequenceId,
      details: { region: seq.region, gateway: route.gwName, reason: 'gateway_not_configured', environment },
    });
    return {
      transmitted: false,
      reason: 'gateway_not_configured',
      skipAudit,
      region: seq.region,
      gateway: route.gwName,
      dispatchStatus: seq.dispatchStatus ?? 'pending',
    };
  }

  /* Claim the send before a single byte is assembled or transmitted. Past this
     point a concurrent caller is refused by the compare-and-set rather than by a
     status it read minutes ago. */
  const attemptId = randomUUID();
  if (!(await claimTransmitSlot(sequenceId, ctx.organizationId, signatureActionId, attemptId))) {
    const fresh = await getSequence(sequenceId, ctx);
    throw new SubmissionError(
      'INVALID_STATE',
      resendRefusal(fresh.dispatchStatus) ??
        `Sequence ${sequenceId} is no longer in a transmittable state (dispatch status '${fresh.dispatchStatus ?? 'unknown'}').`,
    );
  }

  // Assemble the package bytes, then hand them to the gateway. A failure
  // anywhere below and BEFORE gw.transmit released nothing to the agency, so the
  // claim taken above is released and the sequence stays transmittable.
  const { assembleSequence } = await import('../ectd/assemble-from-core');
  let assembled;
  try {
    assembled = await assembleSequence({
    sequenceId,
    organizationId: ctx.organizationId,
    userId: ctx.userId,
    // Never fabricate an agency identifier (regulatory-identifiers.ts): these
    // become <application-number>/<procedure-number>, <id>/<company-id> and
    // <name>/<company-name> in the regional backbone, and the application id is
    // also a package filename component. An unassigned value SAYS it is
    // unassigned, in the wording the transmit path already uses.
    applicationId,
      // The applicant's <id> (D-U-N-S) has no recorded home on this path yet
      // (package-identity.ts header); its name is the organisation's.
      sponsorId: params.sponsorId ?? `UNASSIGNED-ORG-${ctx.organizationId}`,
      sponsorName: applicantName,
    });
  } catch (err) {
    await releaseTransmitSlot(sequenceId, ctx.organizationId, signatureActionId, attemptId);
    throw err;
  }

  // A dossier transmitted to an agency must physically contain every leaf's
  // file. `assemble` surfaces every leaf whose source could not be materialized
  // into the package — and the packager DROPS those leaves from the ZIP
  // (resolveFile → null → skipped). That is true for BOTH a genuine defect (a
  // coauthor/unified row missing in the org, or an unsupported document_table)
  // AND a known-external pointer (vault S3 / ctd_onboarding upload) whose bytes
  // were not fetched into the package: in either case the transmitted sequence
  // would be MISSING that document. There is no "external reference" in an eCTD
  // backbone — a leaf resolves to a file inside the sequence. So fail closed on
  // ANY unresolved leaf (release the staged bundle and block), classifying the
  // cause only for the operator message.
  const unresolved = assembled.unresolvedLeaves;
  if (unresolved.length > 0) {
    await assembled.cleanup();
    const isExternal = (l: { documentTable: string | null }) =>
      externalDocumentTableReason(l.documentTable) !== null;
    const defects = unresolved.filter((l) => !isExternal(l));
    const external = unresolved.filter(isExternal);
    const parts: string[] = [];
    if (defects.length > 0) {
      parts.push(
        `${defects.length} reference a document that could not be assembled ` +
          `(${defects.map((d) => `${d.documentTable}:${d.documentId}`).join(', ')})`,
      );
    }
    if (external.length > 0) {
      parts.push(
        `${external.length} external-storage document(s) (vault/onboarding) whose bytes were not materialized into the package ` +
          `(${external.map((d) => `${d.documentTable}:${d.documentId}`).join(', ')})`,
      );
    }
    await releaseTransmitSlot(sequenceId, ctx.organizationId, signatureActionId, attemptId);
    throw new SubmissionError(
      'DISPATCH_BLOCKED',
      `Transmit blocked — the transmitted sequence would be missing ${unresolved.length} leaf file(s): ${parts.join('; ')}. ` +
        `Every eCTD leaf must be physically present in the package.`,
    );
  }

  // 2026-09-22 (W5/D7): two more ways a sequence reached the gateway missing
  // what the author placed — a leaf left out of the ZIP (`skipped`) and a draft
  // leaf shipped in it (`unfinalized`) — both computed by assembly and read by
  // nobody here. See assembledTransmitBlockers. The governed freeze and dispatch
  // now refuse on the same rule before the leaves lock (assertSequencePackageable),
  // so this is the re-check at the irreversible step; the claim is released
  // because nothing was sent.
  const { assembledTransmitBlockers } = await import('../ectd/assemble-from-core');
  const gaps = assembledTransmitBlockers(assembled);
  if (gaps.length > 0) {
    await assembled.cleanup();
    await releaseTransmitSlot(sequenceId, ctx.organizationId, signatureActionId, attemptId);
    throw new SubmissionError(
      'DISPATCH_BLOCKED',
      `Transmit blocked — ${gaps.join('; ')}. A transmitted sequence must carry every placed leaf, and only approved documents.`,
    );
  }

  let result;
  try {
    attempt.reachedGateway = true;
    result = await gw.transmit({
      organizationId: ctx.organizationId,
      userId: ctx.userId,
      // The transmittal names the project its submission belongs to (LX-22):
      // submission_transmittals.program_id, which every gateway copies from
      // here, was always NULL on this path.
      programId: submission.programId ?? null,
      packageId: null,
      bundle: assembled.bundle,
      environment,
      submissionType: seq.type ?? undefined,
      metadata: { applicationId, sequence: seq.sequenceNumber, environment },
      // This internal field is not accepted by the public governed HTTP route.
      dispatchBinding: { attemptId, organizationId: ctx.organizationId, sequenceId, signatureActionId, bundleSha256: assembled.bundle.sha256 },
      // Gate 1 above already verified this signature governs THIS sequence and
      // was made by THIS actor; the gateway layer now requires that proof to be
      // named rather than merely to have happened somewhere up the stack.
      authorization: {
        kind: 'governed-signature',
        signatureActionId,
        actorUserId: ctx.userId,
      },
    });
  } catch (err) {
    // The guard refused before handing anything to the gateway: nothing was
    // sent, so the claim is released and the sequence stays transmittable.
    // Any other failure may have reached the agency and is left for a human.
    // 2026-09-23 (W5/D7).
    const { refusedBeforeWire } = await import('../submission-gateways/index');
    if (refusedBeforeWire(err)) await releaseTransmitSlot(sequenceId, ctx.organizationId, signatureActionId, attemptId);
    throw err;
  } finally {
    // The gateway has consumed the bundle bytes (or failed); either way the
    // staged temp package is no longer needed.
    await assembled.cleanup();
  }

  const dispatchStatus = toDispatchStatus(result.status);
  // null = the guard reported nothing (never read as "all passed"). The one
  // reduction the governed transmit records too (2026-09-23, W5/D7, round-2
  // review) — it used to be computed inline here only.
  const preTransmit = preTransmitFindings(result);
  await applySequenceChangeWithAudit(
    {
      // Predicated on the claim taken before the wire: this row is the one that
      // resolves THIS attempt. If the §11.10(e) write fails, applySequenceChange-
      // WithAudit rolls this back and the sequence stays 'transmitting' — bytes
      // are already at the agency, so the correct posture is a state a human must
      // resolve, not 'pending', which silently invited a second send.
      text: `UPDATE ectd_sequences SET dispatch_status = $1, updated_at = NOW() WHERE id = $2 AND organization_id = $3 AND dispatch_status = $4 AND transmit_signature_action_id = $5 AND transmit_attempt_id = $6`,
      params: [dispatchStatus, sequenceId, ctx.organizationId, TRANSMITTING_STATUS, signatureActionId, attemptId],
      noRowsRefusal:
        `Sequence ${sequenceId} was no longer the in-flight transmit when the result came back; ` +
        `its dispatch status was resolved by something else. The package WAS handed to the gateway — ` +
        `confirm at the agency before any further action.`,
    },
    {
      organizationId: ctx.organizationId,
      userId: ctx.userId,
      action: 'ECTD_TRANSMITTED',
      resourceId: sequenceId,
      details: {
        region: seq.region,
        gateway: route.gwName,
        transmittalId: result.transmittalId,
        transmissionId: result.transmissionId ?? null,
        status: result.status,
        environment,
        signatureActionId,
        // The package checks that FAILED without blocking, and the guard's
        // warnings, on the §11.10(e) record of the send (2026-09-22, W5/D7).
        preTransmitFailedChecks: preTransmit.failedChecks,
        preTransmitWarnings: preTransmit.warnings,
        // P-34: the waiver the send went forward on, when no review had completed.
        ...withWaiverReliedOn(assessment),
      },
    },
  );
  logger.info('Transmitted sequence to agency gateway', { sequenceId, region: seq.region, gateway: route.gwName, status: result.status });

  return {
    transmitted: true,
    region: seq.region,
    gateway: route.gwName,
    transmittalId: result.transmittalId,
    transmissionId: result.transmissionId,
    status: result.status,
    dispatchStatus,
    preTransmitFailedChecks: preTransmit.failedChecks,
    preTransmitWarnings: preTransmit.warnings,
  };
}

// ── Leaves (Builder tree) ──────────────────────────────────────────────────

export async function listLeaves(
  sequenceId: number,
  ctx: { organizationId: number }
): Promise<SubmissionLeaf[]> {
  await getSequence(sequenceId, ctx);
  const rows = await db
    .select()
    .from(submissionLeaves)
    .where(
      and(
        eq(submissionLeaves.sequenceId, sequenceId),
        eq(submissionLeaves.organizationId, ctx.organizationId),
        isNull(submissionLeaves.deletedAt)
      )
    )
    .orderBy(submissionLeaves.sectionCode);
  return rows as SubmissionLeaf[];
}

export interface UpsertLeafInput {
  sequenceId: number;
  leafId?: number; // when set, update; else insert
  sectionCode: string;
  title: string;
  granularity?: string | null;
  lifecycleOp?: string;
  documentTable?: string | null;
  documentId?: number | null;
  /** The uuid half of the polymorphic reference, for uuid-keyed stores
   *  (vault.documents). A leaf carries this OR documentId, never both. */
  documentUuid?: string | null;
  documentType?: string | null;
  parentLeafId?: number | null;
  /** MD5 (or other) checksum of the leaf's rendered bytes, for the eCTD index-md5. */
  checksum?: string | null;
  /** Why this placement was made, recorded on its audit row (21 CFR 11.10(e)).
   *  The human door (PUT /api/submissions/sequences/:seqId/leaves) requires it
   *  through `requireGovernedReason`; the service callers that place on a
   *  person's earlier decision (IND lifecycle, CMC Module 3, ingestion) may omit
   *  it. It is recorded exactly as given and never substituted. */
  reason?: string | null;
}

/**
 * Tenancy + source pin for a leaf's document pointer, one entry per document
 * table the READ side (server/services/ectd/leaf-source-resolver.ts) can
 * materialize.
 *
 * ── Why a table-keyed dispatch and not another `if` ──────────────────────────
 * This block used to be two hand-written `if (input.documentTable === …)`
 * branches — coauthor_documents and rendered_leaf_files — under a comment
 * promising "no dangling cross-tenant document pointers". The resolver could
 * materialize five tables. The other three (unified_documents,
 * ctd_onboarding_documents, c2c_document_sections) were written straight
 * through: any id, from any organization or from nothing at all, was stored
 * verbatim and left unpinned. The read side fails closed per table, so no
 * foreign bytes ever reached a package — but dispatch readiness only checks
 * that a pointer is PRESENT, so such a sequence reads as READY and only falls
 * over at assembly as an `unresolved` leaf.
 *
 * Each verifier proves the document resolves IN THE CALLER'S ORGANIZATION
 * (throwing FORBIDDEN otherwise) and returns the digest to pin, taken from the
 * SAME org-scoped read — a second query could race a concurrent edit and pin
 * content the tenancy check never saw. Its predicate mirrors the resolver's for
 * that table exactly; when a new source is added there, the drift guard in
 * __tests__/leaf-source-tenancy.pglite.test.ts fails until it is added here.
 *
 * NULL, never sha256(''), is the pin for every "nothing to pin" case: sha256('')
 * is a real constant that would look exactly like a pin that had been taken and
 * would then "match" any other empty document forever.
 */
type LeafSourceVerifier = (documentId: number, organizationId: number) => Promise<string | null>;

const forbidRef = () =>
  new SubmissionError('FORBIDDEN', 'Referenced document not found for this organization.');

const sha256Hex = (value: string | Buffer): string =>
  createHash('sha256')
    .update(typeof value === 'string' ? Buffer.from(value, 'utf8') : value)
    .digest('hex');

/**
 * The status an authoring filing copy carries at this write (draft, finalized,
 * approved; coauthor-snapshot.ts takes it from the source when the copy is
 * taken). Recorded on the leaf's ledger row, because re-placing a copy that was
 * approved without its text changing leaves the pin, and so documentChanged,
 * as they were: without the status the row could not show draft → approved.
 * Other stores carry no copy status, and null claims nothing.
 */
async function placedCopyStatus(
  documentTable: string | null | undefined,
  documentId: number | null | undefined,
  organizationId: number,
): Promise<string | null> {
  if (documentTable !== 'coauthor_documents' || documentId == null) return null;
  const [doc] = await db
    .select({ status: coauthorDocuments.status })
    .from(coauthorDocuments)
    .where(and(eq(coauthorDocuments.id, documentId), eq(coauthorDocuments.organizationId, organizationId)))
    .limit(1);
  return doc?.status ?? null;
}

const LEAF_SOURCE_VERIFIERS: Record<string, LeafSourceVerifier> = {
  /** Authoring store. Pin = sha256 of the stored body text. */
  coauthor_documents: async (documentId, organizationId) => {
    const [doc] = await db
      .select({ id: coauthorDocuments.id, content: coauthorDocuments.content })
      .from(coauthorDocuments)
      .where(and(eq(coauthorDocuments.id, documentId), eq(coauthorDocuments.organizationId, organizationId)))
      .limit(1);
    if (!doc) throw forbidRef();
    return typeof doc.content === 'string' && doc.content.length > 0 ? sha256Hex(doc.content) : null;
  },

  /* Bytes this server rendered for a filing. The pin is the sha256 recorded
     when the bytes were rendered, which is exactly what the resolver
     re-verifies before staging them. */
  rendered_leaf_files: async (documentId, organizationId) => {
    const [rendered] = await db
      .select({ sha256: renderedLeafFiles.sha256 })
      .from(renderedLeafFiles)
      .where(and(eq(renderedLeafFiles.id, documentId), eq(renderedLeafFiles.organizationId, organizationId)))
      .limit(1);
    if (!rendered) throw forbidRef();
    return rendered.sha256;
  },

  /* Unified workflow document: the row is the tenant boundary, the body lives
     in the latest workflow_document_versions row (read org-scoped directly, as
     the resolver does, not only transitively through the parent).

     The pin is over JSON.stringify(version.content). That is a CHANGE
     DETECTOR, not a canonical serialization: it depends on the driver
     preserving stored key order, so a pin that stops matching after a driver or
     column-type change is not by itself tamper evidence. It is pinned this way
     because an inspector can re-derive it from that single column; digesting
     rendered text instead would drift with the renderer. */
  unified_documents: async (documentId, organizationId) => {
    const [doc] = await db
      .select({ id: unifiedDocuments.id })
      .from(unifiedDocuments)
      .where(and(eq(unifiedDocuments.id, documentId), eq(unifiedDocuments.organizationId, organizationId)))
      .limit(1);
    if (!doc) throw forbidRef();
    const [version] = await db
      .select({ content: workflowDocumentVersions.content })
      .from(workflowDocumentVersions)
      .where(
        and(
          eq(workflowDocumentVersions.documentId, documentId),
          eq(workflowDocumentVersions.organizationId, organizationId),
        ),
      )
      .orderBy(desc(workflowDocumentVersions.version))
      .limit(1);
    return version && version.content != null ? sha256Hex(JSON.stringify(version.content)) : null;
  },

  /* Uploaded CTD binary. Tenancy is the row's organization_id; the pin is the
     sha256 of the upload's bytes.

     The byte read fails SOFT (pin NULL when the file is missing/rotated): the
     placement is a metadata write, and making it depend on disk availability
     would refuse a leaf the assembler can still legitimately report as
     unresolved. Tenancy itself never fails soft — the row lookup above already
     decided that. */
  ctd_onboarding_documents: async (documentId, organizationId) => {
    const [doc] = await db
      .select({ storagePath: ctdOnboardingDocuments.storagePath })
      .from(ctdOnboardingDocuments)
      .where(and(eq(ctdOnboardingDocuments.id, documentId), eq(ctdOnboardingDocuments.organizationId, organizationId)))
      .limit(1);
    if (!doc) throw forbidRef();
    let buf: Buffer | null;
    try {
      buf = await readLocalUploadBuffer(doc.storagePath);
    } catch {
      buf = null;
    }
    return buf && buf.length > 0 ? sha256Hex(buf) : null;
  },

  /* Governed authoring store (MDR/IVDR). c2c_document_sections carries NO
     organization column: its tenant scope is the parent c2c_documents.org_id,
     so the JOIN below IS the tenant gate — exactly the predicate the resolver
     uses. Issued through drizzle's `db.execute` so the same PGlite harness the
     sibling branches use covers it. Pin = sha256 of the canonical section text
     (sectionPlainText), the same reading of the body the packager renders. */
  c2c_document_sections: async (documentId, organizationId) => {
    const res = await db.execute(sql`
      SELECT s.content
        FROM c2c_document_sections s
        JOIN c2c_documents d ON d.id = s.document_id
       WHERE s.id = ${documentId} AND d.org_id = ${organizationId}
       LIMIT 1`);
    const rows = ((res as unknown as { rows?: unknown[] }).rows ?? res) as Array<{ content: unknown }>;
    if (!rows[0]) throw forbidRef();
    // jsonb arrives parsed from node-postgres and PGlite; tolerate a driver
    // that hands back the serialized string.
    let content: unknown = rows[0].content;
    if (typeof content === 'string') {
      try { content = JSON.parse(content); } catch { /* keep as text */ }
    }
    const text = sectionPlainText(content).trim();
    return text ? sha256Hex(text) : null;
  },
};

/**
 * The document tables upsertLeaf verifies tenancy for. Exported so the drift
 * guard can assert this set still covers everything the read-side resolver
 * branches on — a new resolver source with no verifier here would be storable
 * unchecked and unpinned, which is the defect this dispatch closes.
 */
/**
 * Verifiers for UUID-KEYED stores. Same contract as LEAF_SOURCE_VERIFIERS —
 * prove the document resolves in the caller's organization, return the digest
 * to pin, take both from one org-scoped read — but keyed by uuid rather than by
 * integer, because `submission_leaves` addresses two key spaces
 * (migrations/20260917b_submission_leaf_document_uuid.sql).
 *
 * Kept as a SECOND map rather than widening every existing verifier's
 * signature: the integer verifiers are correct and their predicates mirror the
 * resolver's branch for their table exactly, and rewriting five of them to
 * carry a parameter four will never use is churn on the code path that decides
 * what reaches a regulator.
 */
type LeafSourceUuidVerifier = (documentUuid: string, organizationId: number) => Promise<string | null>;

/** Guards the ::uuid cast; a malformed value would raise 22P02 rather than a refusal. */
const LEAF_UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const LEAF_SOURCE_UUID_VERIFIERS: Record<string, LeafSourceUuidVerifier> = {
  /* The vault. Scoped THROUGH THE PROGRAMME, which is the authoritative owner
     of a vault document — vault.documents carries organization_id too, but it
     is nullable by design (unattributable rows are quarantined) and so is
     attribution rather than a scope to filter on. Pin = content_hash, which is
     exactly what the resolver re-verifies before staging the bytes, so a source
     altered after filing is detectable at assembly. */
  vault_documents: async (documentUuid, organizationId) => {
    if (!LEAF_UUID_RE.test(documentUuid)) throw forbidRef();
    const res = await pool.query(
      `SELECT d.content_hash
         FROM vault.documents d
        WHERE d.id = $1::uuid
          AND d.deleted_at IS NULL
          AND EXISTS (
            SELECT 1 FROM regulatory_programs rp
             WHERE rp.id = d.program_id
               AND rp.organization_id = $2
               AND rp.deleted_at IS NULL
          )
        LIMIT 1`,
      [documentUuid, organizationId],
    );
    const row = res.rows[0] as { content_hash: string | null } | undefined;
    if (!row) throw forbidRef();
    return row.content_hash ?? null;
  },
};

/** The document tables that name their document by UUID rather than by integer. */
export const LEAF_UUID_KEYED_TABLES: ReadonlySet<string> = new Set(Object.keys(LEAF_SOURCE_UUID_VERIFIERS));

export const LEAF_SOURCE_TENANCY_TABLES: ReadonlySet<string> = new Set([
  ...Object.keys(LEAF_SOURCE_VERIFIERS),
  ...Object.keys(LEAF_SOURCE_UUID_VERIFIERS),
]);

/**
 * Prove the referenced document belongs to `organizationId` and return the
 * digest to pin on the leaf (null when there is nothing to pin).
 *
 * A table with no registered verifier (vault_documents — UUID-keyed and
 * program-scoped, so an integer leaf id cannot address it tenant-safely — or an
 * unknown string) keeps today's behaviour: stored unverified and unpinned, and
 * surfaced as an unresolved leaf at assembly. Widening that is a separate
 * decision; the drift guard exists so it is a decision rather than an omission.
 */
async function verifyLeafSource(
  documentTable: string,
  ref: { documentId: number | null; documentUuid: string | null },
  organizationId: number,
): Promise<string | null> {
  if (ref.documentUuid) {
    const verifyUuid = LEAF_SOURCE_UUID_VERIFIERS[documentTable];
    return verifyUuid ? verifyUuid(ref.documentUuid, organizationId) : null;
  }
  if (ref.documentId) {
    const verify = LEAF_SOURCE_VERIFIERS[documentTable];
    return verify ? verify(ref.documentId, organizationId) : null;
  }
  return null;
}

/**
 * A created or updated leaf placement, with what happened to the §11.10(e)
 * record of that placement carried on it.
 *
 * WO-16C #133. Both audit writes in `upsertLeaf` — `LEAF_CREATED` on the insert
 * branch, `LEAF_UPDATED` on the update branch — were awaited at statement
 * position with their `AuditWriteResult` discarded. A placement decides where a
 * document is filed in a package that goes to an agency, and every write path
 * funnels through here: the REST route (PUT
 * /api/submissions/sequences/:seqId/leaves), AnA's `place_into_sequence`, the
 * IND lifecycle persistence, the IND forms route and CMC Module 3 placement.
 * Each got a leaf row back and no way to tell a recorded placement from an
 * unrecorded one.
 *
 * Exactly ONE of the two rows is written per call — the branches are mutually
 * exclusive on `input.leafId` — so `auditTrail` is always that one row's
 * outcome and is never another row's under a borrowed name; which action it was
 * is the same distinction as which branch ran.
 */
/**
 * What a leaf write returns. `auditTrail` is the §11.10(e) outcome of the write
 * made. A write that changed nothing (`unchanged`, see upsertLeaf) made no audit
 * row, so it carries none (null) and must not be read as an unpersisted audit.
 */
export type UpsertedLeaf = SubmissionLeaf & {
  auditTrail: AuditRowOutcome | null;
  unchanged?: true;
  /** Set when the write returned a Validated sequence to Assembling. */
  sequenceStatusChanged?: LeafWriteSequenceChange;
};

/** Create or update a leaf placement. Refuses if the parent sequence is locked. */
/**
 * The section-code vocabulary this sequence's leaves are judged against, read
 * from its submission's `applicationType`.
 *
 * Fails SAFE, not open: a submission row that cannot be read gives `ctd`, the
 * strictest vocabulary and the one every submission in this product uses
 * today. A lookup failure must never widen what may be written into a package.
 */
async function placementVocabularyForSequence(
  seq: EctdSequence,
  ctx: { organizationId: number },
): Promise<{ vocabulary: PlacementVocabulary; programId: string | null; applicationType: string | null }> {
  const rows = await db
    .select({ applicationType: submissions.applicationType, programId: submissions.programId })
    .from(submissions)
    .where(and(eq(submissions.id, seq.submissionId), eq(submissions.organizationId, ctx.organizationId)))
    .limit(1);
  // Defensive destructure rather than `const [row] =`: this read only decides
  // how STRICT the code gate is, and a shape it did not expect must narrow to
  // `ctd`, never throw a placement away. The same read gives the project the
  // submission belongs to (LX-22), which a placement must stay inside.
  const row = Array.isArray(rows) ? rows[0] : undefined;
  return {
    vocabulary: vocabularyForApplicationType(row?.applicationType ?? null),
    programId: row?.programId ?? null,
    applicationType: row?.applicationType ?? null,
  };
}

type LeafRef = { documentId: number | null; documentUuid: string | null };

/** Per store that records a project: the read of a document's project. */
const LEAF_PROGRAM_READS: Record<string, (ref: LeafRef, organizationId: number) => ReturnType<typeof sql> | null> = {
  /* Through the program, as the tenancy verifier scopes it: organization_id is
     nullable on vault.documents, and filtering on it would read an unattributed
     document as having no project, which skips the cross-project check. */
  vault_documents: (ref, organizationId) =>
    ref.documentUuid
      ? sql`
      SELECT d.program_id::text AS program_id
        FROM vault.documents d JOIN regulatory_programs rp ON rp.id = d.program_id
       WHERE d.id = ${ref.documentUuid}::uuid AND rp.organization_id = ${organizationId}`
      : null,
  c2c_document_sections: (ref, organizationId) =>
    ref.documentId
      ? sql`
      SELECT d.project_id::text AS program_id
        FROM c2c_document_sections s JOIN c2c_documents d ON d.id = s.document_id
       WHERE s.id = ${ref.documentId} AND d.org_id = ${organizationId}`
      : null,
  coauthor_documents: (ref, organizationId) =>
    ref.documentId
      ? sql`
      SELECT ad.client_program_id::text AS program_id
        FROM c2c_document_aliases a JOIN authoring_documents ad ON ad.id = a.canonical_id
       WHERE a.store = 'coauthor_documents' AND a.native_id = ${String(ref.documentId)}
         AND a.organization_id = ${organizationId} AND ad.tenant_id = ${organizationId}`
      : null,
};

/** The SQLSTATE of a failed statement; Drizzle wraps the driver's error. */
function sqlStateOf(err: unknown): string | undefined {
  const e = err as { code?: string; cause?: { code?: string } } | null;
  return e?.code ?? e?.cause?.code;
}

/**
 * The project (regulatory_programs.id) a leaf's document belongs to, where its
 * store records one: a Vault document's program, a governed section's filing
 * document's project, an authoring filing copy's document's project (through
 * its alias). Null where the store records none. Called after verifyLeafSource,
 * so tenancy is already proven. A store this database does not carry (42P01 /
 * 42703) records nothing; any other failure propagates — a placement is never
 * allowed because its project could not be read.
 */
async function leafSourceProgram(documentTable: string, ref: LeafRef, organizationId: number): Promise<string | null> {
  const query = LEAF_PROGRAM_READS[documentTable]?.(ref, organizationId) ?? null;
  if (!query) return null;
  try {
    const res = (await db.execute(query)) as unknown as { rows?: unknown[] } | unknown[] | undefined;
    const rows = ((res && !Array.isArray(res) ? res.rows : res) ?? []) as Array<{ program_id: string | null }>;
    return rows[0]?.program_id ?? null;
  } catch (err) {
    const code = sqlStateOf(err);
    if (code === '42P01' || code === '42703') return null;
    throw err;
  }
}

/** A transaction handle from `db.transaction` — what a locked leaf write runs on. */
type LeafWriteTx = Parameters<Parameters<typeof db.transaction>[0]>[0];

/**
 * The live leaf of this sequence that already names this document in this
 * section, or null. Compared by document identity (table plus uuid or id) and by
 * section, case- and space-insensitively, the way the lifecycle keys compare
 * sections (sharedLifecycleKeys). Reads only live leaves: a removed leaf does not
 * count as a placement.
 */
async function sameDocumentLeafInSection(
  executor: Pick<LeafWriteTx, 'select'>,
  input: UpsertLeafInput,
  organizationId: number,
): Promise<SubmissionLeaf | null> {
  if (!input.documentTable) return null;
  const document =
    input.documentUuid != null
      ? eq(submissionLeaves.documentUuid, input.documentUuid)
      : input.documentId != null
        ? eq(submissionLeaves.documentId, input.documentId)
        : null;
  if (!document) return null;
  const [row] = await executor
    .select()
    .from(submissionLeaves)
    .where(
      and(
        eq(submissionLeaves.sequenceId, input.sequenceId),
        eq(submissionLeaves.organizationId, organizationId),
        isNull(submissionLeaves.deletedAt),
        eq(submissionLeaves.documentTable, input.documentTable),
        document,
        sql`lower(btrim(${submissionLeaves.sectionCode})) = lower(btrim(${input.sectionCode}))`,
      ),
    )
    .limit(1);
  return (row as SubmissionLeaf | undefined) ?? null;
}

/**
 * Run a leaf write in one transaction holding the sequence row lock
 * (SELECT … FOR UPDATE) — the lock the governed freeze/dispatch takes before
 * its compare-and-set — and re-check, UNDER that lock, that the sequence is not
 * frozen or dispatched.
 *
 * 2026-09-23 (W5/D7, round-2 skeptic). upsertLeaf and removeLeaf read the
 * status, then did several more round-trips (vocabulary, tenancy, parent),
 * then wrote with no lock, so a freeze that committed in between left a leaf
 * written into (or taken out of) a frozen sequence; and a write landing while
 * the freeze gate assembled was frozen unjudged. With both sides taking this
 * lock, a leaf write either commits before the freeze's lock — and the freeze
 * sees the changed leaf-manifest digest and refuses — or waits for it, and
 * then sees 'frozen' here and refuses. Both interleavings are exercised on two
 * real Postgres connections in __tests__/freeze-gate-row-lock.pg.test.ts.
 *
 * 2026-09-23 (W5/D7, round-2 skeptic, second pass): this serializes the leaf
 * writers that go through it — upsertLeaf and removeLeaf — and no others.
 * 2026-09-23 (W5/D7, residual repair): ingestion-service's classifyDocument,
 * which inserted into submission_leaves directly (no status check, no lock),
 * now places through upsertLeaf and reports its refusal on the classification
 * result, so the product has no leaf writer that bypasses this lock.
 */
async function lockSequenceForLeafWrite<T>(
  sequenceId: number,
  ctx: { organizationId: number },
  write: (tx: LeafWriteTx) => Promise<T>,
  /** Whether `write`'s result changed a leaf. A no-op leaves Validated standing. */
  changed: (result: T) => boolean = () => true,
): Promise<{ value: T; revertedFromValidated: boolean }> {
  return db.transaction(async (tx) => {
    const locked = await tx.execute(sql`
      SELECT status FROM ectd_sequences
       WHERE id = ${sequenceId} AND organization_id = ${ctx.organizationId} AND deleted_at IS NULL
       FOR UPDATE`);
    const row = ((locked as unknown as { rows?: Array<{ status: string }> }).rows ?? [])[0];
    if (!row) throw new SubmissionError('NOT_FOUND', 'Sequence not found for this organization.');
    if (isSequenceLocked(row.status)) {
      throw new SubmissionError('INVALID_STATE', `Sequence is ${row.status}; its leaves are immutable.`);
    }
    const value = await write(tx);
    /* QA 2026-10-08 (j6, finding 3): a leaf placed into a Validated sequence
       left it Validated, so the status claimed a validation of content that
       had changed. A leaf change now returns the sequence to Assembling and
       clears its recorded verdict, in the same transaction and under the same
       lock as the write, so no reader sees the new leaf beside the old claim. */
    const revertedFromValidated = row.status === 'validated' && changed(value);
    if (revertedFromValidated) {
      await tx.execute(sql`
        UPDATE ectd_sequences SET status = 'assembling', validation_status = NULL, updated_at = NOW()
         WHERE id = ${sequenceId} AND organization_id = ${ctx.organizationId} AND status = 'validated'`);
    }
    return { value, revertedFromValidated };
  });
}

/** What a leaf write did to its sequence's status, when it changed it, and
 *  what became of the §11.10(e) row recording that. */
export type LeafWriteSequenceChange = { from: 'validated'; to: 'assembling'; auditTrail: AuditRowOutcome };

/** The §11.10(e) row for a sequence a leaf write returned to Assembling. The
 *  move is committed with the leaf; a lost row is reported, never undone. */
async function recordRevertedValidation(
  sequenceId: number,
  leafId: number,
  ctx: { organizationId: number; userId: number },
): Promise<LeafWriteSequenceChange> {
  const auditTrail = await recordAuditRow({
    organizationId: ctx.organizationId,
    userId: ctx.userId,
    action: 'SEQUENCE_TRANSITIONED',
    resourceType: 'ectd_sequence',
    resourceId: sequenceId,
    details: { from: 'validated', to: 'assembling', cause: 'leaf_changed', leafId },
  });
  return { from: 'validated', to: 'assembling', auditTrail };
}

export async function upsertLeaf(
  input: UpsertLeafInput,
  ctx: { organizationId: number; userId: number }
): Promise<UpsertedLeaf> {
  const seq = await getSequence(input.sequenceId, ctx);
  if (isSequenceLocked(seq.status)) {
    throw new SubmissionError('INVALID_STATE', `Sequence is ${seq.status}; its leaves are immutable.`);
  }

  /* The leaf's SECTION CODE decides where the document lands in the package:
     the packager derives the leaf's module, its folder and which backbone
     carries it from this string (regional-packager `leafPackagePath`). Nothing
     on the write path constrained it — the route schema takes any 64-character
     string and the placement dialog is a free text input whose own placeholder
     suggested `m1/us/1.2` — so a value that is not a CTD code became a FOLDER
     NAME, and a package shipped with a top-level `mm/m1-us-1-2/` directory and
     a backbone pointing into it.

     The gate is deliberately code-SHAPE, not published-heading membership: four
     of the codes this product itself writes (m1.5, m1.7, m1.9, m1.13 — the IND
     annual report among them) are absent from FDA's published Module 1 table,
     so a placeability gate here would refuse the product's own filings. That
     mismatch is real and reported separately; it is not a reason to reject a
     well-formed code.

     The value is stored EXACTLY as given. Readers match on the spelling that
     was written (the IND checklist looks for `m1.1.1`), so canonicalising here
     would silently detach them from their own rows; the packager canonicalises
     when it derives the layout. */
  /* WHICH vocabulary the code is judged against is a property of the
     SUBMISSION TYPE, not of this function.

     This gate ran `normalizeCtdCode` on every code, which is right for an eCTD
     sequence and refused two whole submission types that do not file on CTD
     headings: a 510(k) files on eSTAR sections, and an IRB package files on
     artifact slots that are not numbered at all. The refusal read as a
     validation error about a malformed code, so it looked like a caller bug
     rather than a missing capability.

     Each type is now judged against its own vocabulary, strictly — the CTD
     branch is byte-for-byte the rule that was here, and an unknown or absent
     application type resolves to `ctd`, so every existing caller behaves
     exactly as before. A bare module ('3') is still a CONTAINER, never a
     place a document can go. */
  const { vocabulary, programId: submissionProgramId, applicationType } = await placementVocabularyForSequence(seq, ctx);
  const verdict = validateSectionCode(input.sectionCode, vocabulary);
  if (!verdict.ok) {
    throw new SubmissionError('VALIDATION', verdict.message ?? `Section code "${input.sectionCode}" is not valid for this submission.`);
  }

  /* The leaf's document pointer is POLYMORPHIC — `document_table` is a plain
     string. Nothing constrained it here, so a misspelled or invented table was
     stored verbatim, audited as a placement, and reported dispatch-CLEAR by the
     readiness validator (which only checks that a pointer is PRESENT); the
     mistake only surfaced at assembly, as an unresolvable leaf, typically at the
     end of a filing window. Refuse it at the write boundary instead — this is
     the single choke point every caller funnels through (the REST route, AnA's
     place_into_sequence, ind-lifecycle persistence and CMC placement). */
  if (input.documentTable != null && !isPlaceableDocumentTable(input.documentTable)) {
    throw new SubmissionError('VALIDATION', unplaceableDocumentTableMessage(input.documentTable));
  }

  /* THE KEY SPACE MUST MATCH THE TABLE. `submission_leaves` addresses two of
     them — integer `document_id` for most stores, uuid `document_uuid` for
     vault.documents — and this is the one place that rule is enforced.
     Deliberately here and not as a CHECK constraint: the constraint would have
     to name tables, which is exactly the vocabulary leaf-document-tables.ts
     owns and keeps in step with the resolver's real branches, and splitting one
     rule across a migration and a module is how the two drift.

     Both directions are refused, because both produce a leaf that looks placed
     and resolves to nothing: a vault leaf with only an integer cannot address
     its document, and an integer-keyed leaf carrying a uuid names a document in
     a store that has no uuids. */
  if (input.documentTable != null) {
    const uuidKeyed = LEAF_UUID_KEYED_TABLES.has(input.documentTable);
    if (uuidKeyed && input.documentId != null) {
      throw new SubmissionError(
        'VALIDATION',
        `"${input.documentTable}" is addressed by document_uuid, not document_id. Its documents are uuid-keyed; an integer cannot name one.`,
      );
    }
    if (!uuidKeyed && input.documentUuid != null) {
      throw new SubmissionError(
        'VALIDATION',
        `"${input.documentTable}" is addressed by document_id, not document_uuid. Only ${[...LEAF_UUID_KEYED_TABLES].sort().join(', ')} name a document by uuid.`,
      );
    }
    if (uuidKeyed && input.documentUuid == null) {
      throw new SubmissionError(
        'VALIDATION',
        `A leaf on "${input.documentTable}" must carry document_uuid — without it the leaf names no document and would be filed as unresolvable.`,
      );
    }
  }

  /* Tenancy + source pin for the document this leaf points at. One table-keyed
     step (LEAF_SOURCE_VERIFIERS above) covers every source the resolver can
     materialize: it proves the target belongs to the caller's org — no dangling
     cross-tenant document pointers — and returns the digest to pin.

     Source pin (GA ledger L23). The leaf records where the document lives and
     the MD5 of its RENDERED bytes; neither says what the SOURCE contained when
     it was filed. So "this went to the agency — is the document behind it still
     what went?" had no answer: `document_id` resolves to the document as it is
     now, and editing it after filing changes nothing on the leaf. */
  const documentContentSha256: string | null =
    input.documentTable && (input.documentId || input.documentUuid)
      ? await verifyLeafSource(
          input.documentTable,
          { documentId: input.documentId ?? null, documentUuid: input.documentUuid ?? null },
          ctx.organizationId,
        )
      : null;

  /* A filing holds only its own project's documents (PF-11). When both are
     recorded — the document's project and the project of the submission this
     sequence belongs to (LX-22) — they must be the same. The organization check
     above let a Vault document of project B be placed, pinned and transmitted
     in project A's filing. A submission that records no project cannot be
     judged; the placement stands and the ledger names both sides. Checked
     before anything is written, on the create and the re-point alike. */
  const documentProgramId =
    input.documentTable && (input.documentId || input.documentUuid)
      ? await leafSourceProgram(
          input.documentTable,
          { documentId: input.documentId ?? null, documentUuid: input.documentUuid ?? null },
          ctx.organizationId,
        )
      : null;
  if (submissionProgramId && documentProgramId && documentProgramId !== submissionProgramId) {
    throw new SubmissionError(
      'CROSS_PROJECT',
      'This document belongs to another project. A filing can hold only its own project’s documents.',
    );
  }
  /* P-14 (docs/LAUNCH_DEFINITION_OF_DONE.md, 2026-10-08): a program's document
     is placed only into a submission anchored to that program. A submission
     that records no program is an unknown dossier, so the placement cannot be
     judged and fails closed; this used to be allowed and only recorded. A
     document whose store records no program is not judged here. */
  if (!submissionProgramId && documentProgramId) {
    throw new SubmissionError(
      'UNANCHORED_SUBMISSION',
      'This submission is not anchored to a project, and this document belongs to one. A project’s document is placed ' +
        'only into a submission anchored to that project, so anchor the submission first: in Submission Center, open ' +
        'this submission and choose “Anchor to a project”. Nothing was placed.',
    );
  }
  // The dedicated library route is not the only Vault placement door: REST,
  // AnA and project Vault placement all reach this canonical writer. Preserve
  // ordinary draft placement while enforcing registered legal applicability.
  if (input.documentTable === 'vault_documents' && input.documentUuid) {
    const country = canonicalRegionOf(seq.region);
    const legalRefusal = await companyLegalVaultTargetRefusal(pool, ctx.organizationId, input.documentUuid, {
      programId: submissionProgramId, country, agency: country ? toAgency(country) : null, submissionType: applicationType,
    });
    if (legalRefusal) throw new SubmissionError('VALIDATION', legalRefusal);
  }
  /* What the ledger records about the document placed (LX-11): which document,
     the pin it took, and both projects. The row said only the sequence, the
     section and a reason. */
  const placedDocument = {
    documentTable: input.documentTable ?? null,
    documentId: input.documentId ?? null,
    documentUuid: input.documentUuid ?? null,
    documentContentSha256,
    documentStatus: await placedCopyStatus(input.documentTable, input.documentId, ctx.organizationId),
    programId: submissionProgramId,
    documentProgramId,
  };

  // A lifecycle op that supersedes a prior leaf (replace|append|delete) carries a
  // parentLeafId — the GUID of the leaf it acts on. That parent MUST belong to the
  // caller's org AND live in THIS sequence; otherwise the eCTD lifecycle chain
  // would link a modified-file operation to a leaf the tenant doesn't own or that
  // sits in another sequence, corrupting the index. (The document pointer above is
  // checked the same way; parentLeafId must not be the weaker link.)
  if (input.parentLeafId != null) {
    const [parent] = await db
      .select({ id: submissionLeaves.id })
      .from(submissionLeaves)
      .where(
        and(
          eq(submissionLeaves.id, input.parentLeafId),
          eq(submissionLeaves.sequenceId, input.sequenceId),
          eq(submissionLeaves.organizationId, ctx.organizationId),
          isNull(submissionLeaves.deletedAt)
        )
      )
      .limit(1);
    if (!parent) {
      throw new SubmissionError(
        'FORBIDDEN',
        'parentLeafId must reference a leaf in this sequence owned by this organization.'
      );
    }
  }

  if (input.leafId) {
    const leafId = input.leafId;
    const leafWhere = and(
      eq(submissionLeaves.id, leafId),
      eq(submissionLeaves.sequenceId, input.sequenceId),
      eq(submissionLeaves.organizationId, ctx.organizationId)
    );
    // Under the sequence row lock (2026-09-23, W5/D7, round-2 skeptic).
    /* The document the leaf pointed at before this write (PF-11): the ledger
       named only the new one, so a re-point left no record of what it replaced.
       Read in the same locked transaction, by the UPDATE's own WHERE. */
    const { value: { previous, rows: updated }, revertedFromValidated } = await lockSequenceForLeafWrite(input.sequenceId, ctx, async (tx) => {
      const [prev] = await tx
        .select({
          documentTable: submissionLeaves.documentTable,
          documentId: submissionLeaves.documentId,
          documentUuid: submissionLeaves.documentUuid,
          documentContentSha256: submissionLeaves.documentContentSha256,
        })
        .from(submissionLeaves)
        .where(leafWhere)
        .for('update');
      const rows = await tx
      .update(submissionLeaves)
      .set({
        sectionCode: input.sectionCode,
        title: input.title,
        granularity: input.granularity ?? null,
        ...(input.lifecycleOp ? { lifecycleOp: input.lifecycleOp } : {}),
        documentTable: input.documentTable ?? null,
        documentId: input.documentId ?? null,
        documentUuid: input.documentUuid ?? null,
        documentType: input.documentType ?? null,
        parentLeafId: input.parentLeafId ?? null,
        ...(input.checksum !== undefined ? { checksum: input.checksum } : {}),
        /* Re-pinned on every update, because an update can re-point the leaf at
           a different document — carrying the previous pin forward would attest
           to content this leaf no longer references. Clearing to NULL when the
           new target has no pinnable content is likewise correct: unknown. */
        documentContentSha256,
        documentPinnedAt: documentContentSha256 ? new Date() : null,
        updatedAt: new Date(),
      })
      .where(leafWhere)
      .returning();
      return { previous: prev ?? null, rows };
    }, (r) => r.rows.length > 0);
    const [row] = updated;
    if (!row) throw new SubmissionError('NOT_FOUND', 'Leaf not found for this organization/sequence.');
    const previousDocument = previous
      ? {
          documentTable: previous.documentTable ?? null,
          documentId: previous.documentId ?? null,
          documentUuid: previous.documentUuid ?? null,
          documentContentSha256: previous.documentContentSha256 ?? null,
        }
      : null;
    const documentChanged =
      previousDocument == null ||
      previousDocument.documentTable !== placedDocument.documentTable ||
      previousDocument.documentId !== placedDocument.documentId ||
      previousDocument.documentUuid !== placedDocument.documentUuid ||
      previousDocument.documentContentSha256 !== placedDocument.documentContentSha256;
    // Part 11 §11.10(e). The UPDATE above is committed (and NOT_FOUND has already
    // been thrown if it matched nothing), so the re-placement is never undone
    // over a lost log row — reverting the pointer would leave the leaf attesting
    // to a document it no longer references. The caller is told instead.
    const auditTrail = await recordAuditRow({
      organizationId: ctx.organizationId,
      userId: ctx.userId,
      action: 'LEAF_UPDATED',
      resourceType: 'submission_leaf',
      resourceId: input.leafId,
      details: {
        sequenceId: input.sequenceId,
        sectionCode: input.sectionCode,
        lifecycleOp: input.lifecycleOp,
        ...placedDocument,
        previousDocument,
        documentChanged,
        ...(input.reason ? { reason: input.reason } : {}),
      },
    });
    const sequenceStatusChanged = revertedFromValidated
      ? await recordRevertedValidation(input.sequenceId, input.leafId, ctx)
      : undefined;
    return { ...(row as SubmissionLeaf), auditTrail, ...(sequenceStatusChanged ? { sequenceStatusChanged } : {}) };
  }

  /* One live leaf per document per section, in one sequence (QA j3 finding (a),
     2026-10-08). The same file placed twice under one section became two leaves
     the packager names one output file for, and the placement dialog gave no
     notice. Judged INSIDE the sequence lock, so two identical placements racing
     cannot both insert.

     A DIFFERENT document may still share a section: several New leaves in one
     section is a readiness INFO (dispatch-readiness DUPLICATE_NEW_SECTION, "without
     erroring"), not a refusal, so it is not judged here. */
  const { value: placed, revertedFromValidated } = await lockSequenceForLeafWrite(input.sequenceId, ctx, async (tx) => {
    const live = await sameDocumentLeafInSection(tx, input, ctx.organizationId);
    if (live) return { kind: 'live' as const, live };
    const [inserted] = await tx
      .insert(submissionLeaves)
      .values({
        sequenceId: input.sequenceId,
        sectionCode: input.sectionCode,
        title: input.title,
        granularity: input.granularity ?? null,
        lifecycleOp: input.lifecycleOp ?? 'new',
        documentTable: input.documentTable ?? null,
        documentId: input.documentId ?? null,
        documentUuid: input.documentUuid ?? null,
        documentType: input.documentType ?? null,
        parentLeafId: input.parentLeafId ?? null,
        checksum: input.checksum ?? null,
        documentContentSha256,
        documentPinnedAt: documentContentSha256 ? new Date() : null,
        organizationId: ctx.organizationId,
        createdBy: ctx.userId,
      })
      .returning();
    return { kind: 'inserted' as const, inserted };
  }, (r) => r.kind === 'inserted');
  if (placed.kind === 'live') return alreadyPlaced(placed.live, input, documentContentSha256);
  const row = placed.inserted;
  // Part 11 §11.10(e), on the same terms as the update branch: the INSERT above
  // is committed, the placement stands, and the outcome rides out on the row.
  const auditTrail = await recordAuditRow({
    organizationId: ctx.organizationId,
    userId: ctx.userId,
    action: 'LEAF_CREATED',
    resourceType: 'submission_leaf',
    resourceId: row.id,
    details: {
      sequenceId: input.sequenceId,
      sectionCode: input.sectionCode,
      ...placedDocument,
      ...(input.reason ? { reason: input.reason } : {}),
    },
  });
  const sequenceStatusChanged = revertedFromValidated
    ? await recordRevertedValidation(input.sequenceId, row.id, ctx)
    : undefined;
  return { ...(row as SubmissionLeaf), auditTrail, ...(sequenceStatusChanged ? { sequenceStatusChanged } : {}) };
}

/**
 * The answer to a new placement of a document that is already live in the
 * section. The same operation is a no-op: the existing leaf comes back, nothing
 * is written and nothing is audited. A different operation is refused by name,
 * because handing back a leaf the caller did not ask for would read as a
 * placement that did not happen.
 *
 * 2026-10-08 (QA walk 2, j4 blocker): "unchanged" also means the leaf's pin
 * still matches the document. A document whose content changed after its leaf
 * pinned it was answered `unchanged: true`, and the placement dialog said
 * "Already placed … holds this document. Nothing was written" over a leaf that
 * no longer held what the document says. That placement is refused by name
 * too; nothing is written, and re-pinning stays an explicit act (remove the
 * leaf and place again).
 */
function alreadyPlaced(live: SubmissionLeaf, input: UpsertLeafInput, currentSha256: string | null): UpsertedLeaf {
  const requested = input.lifecycleOp ?? 'new';
  if ((live.lifecycleOp ?? 'new') !== requested) {
    throw new SubmissionError(
      'ALREADY_PLACED',
      `This document is already placed at ${live.sectionCode} in this sequence as ${live.lifecycleOp} (leaf ${live.id}). ` +
        'Nothing was written. To change its operation, remove that leaf first.',
    );
  }
  if ((live.documentContentSha256 ?? null) !== currentSha256) {
    throw new SubmissionError(
      'ALREADY_PLACED',
      `This document is already placed at ${live.sectionCode} in this sequence (leaf ${live.id}), and its content has ` +
        'changed since that leaf pinned it. Nothing was written. To file the content as it is now, remove that leaf, ' +
        'then place the document again.',
    );
  }
  return { ...live, auditTrail: null, unchanged: true };
}

/**
 * Remove a misplaced leaf from a DRAFT-stage sequence (BP-W1-6 find F05: a
 * wrong placement could only be corrected in place, never removed — the first
 * end-to-end chain exercise had to clean its own mistakes with SQL).
 *
 * Soft delete, because every reader of `submission_leaves` — listLeaves, the
 * assembler, dispatch readiness — already filters `deleted_at IS NULL`, and a
 * hard delete would erase the row an audit event refers to. Guards mirror
 * upsertLeaf: the sequence must belong to the caller's org and must not be
 * frozen/dispatched, and a leaf that another leaf's `parentLeafId` points at
 * cannot be removed — that would orphan the lifecycle chain.
 */
/**
 * What a removal did: which leaf was soft-deleted, and what happened to the
 * §11.10(e) record of the removal.
 *
 * WO-16C #133. This function returned `void`, and its audit write was awaited at
 * statement position with the `AuditWriteResult` discarded — so a caller had
 * nothing at all to distinguish a recorded removal from an unrecorded one. It
 * now returns the outcome. The removal is a SOFT delete, so the fact that the
 * leaf was withdrawn survives in `submission_leaves.deleted_at` independently of
 * this row; what the audit row adds is who withdrew it, when, and from which
 * section — which is why it is reported rather than being allowed to fail
 * silently, and why its loss is still not a reason to put the leaf back.
 *
 * DELETE /api/submissions/sequences/:seqId/leaves/:leafId answers 204 with an
 * empty body today and therefore does not yet forward this; carrying it into the
 * response is a change to that route, not to this service.
 */
export type RemovedLeaf = {
  leafId: number;
  auditTrail: AuditRowOutcome;
  /** Set when the removal returned a Validated sequence to Assembling. */
  sequenceStatusChanged?: LeafWriteSequenceChange;
};

export async function removeLeaf(
  leafId: number,
  sequenceId: number,
  ctx: { organizationId: number; userId: number },
  /** Why the leaf is removed, recorded on the LEAF_REMOVED row exactly as
   *  given (the human door requires it, as it does for a placement). */
  reason?: string | null,
): Promise<RemovedLeaf> {
  const seq = await getSequence(sequenceId, ctx);
  if (isSequenceLocked(seq.status)) {
    throw new SubmissionError('INVALID_STATE', `Sequence is ${seq.status}; its leaves are immutable.`);
  }

  const [dependent] = await db
    .select({ id: submissionLeaves.id })
    .from(submissionLeaves)
    .where(
      and(
        eq(submissionLeaves.parentLeafId, leafId),
        eq(submissionLeaves.organizationId, ctx.organizationId),
        isNull(submissionLeaves.deletedAt)
      )
    )
    .limit(1);
  if (dependent) {
    throw new SubmissionError(
      'INVALID_STATE',
      'Another leaf’s lifecycle operation references this leaf; remove or re-point that leaf first.'
    );
  }

  // Under the sequence row lock (2026-09-23, W5/D7, round-2 skeptic).
  const { value: [row], revertedFromValidated } = await lockSequenceForLeafWrite(sequenceId, ctx, (tx) => tx
    .update(submissionLeaves)
    .set({ deletedAt: new Date(), updatedAt: new Date() })
    .where(
      and(
        eq(submissionLeaves.id, leafId),
        eq(submissionLeaves.sequenceId, sequenceId),
        eq(submissionLeaves.organizationId, ctx.organizationId),
        isNull(submissionLeaves.deletedAt)
      )
    )
    .returning(), (rows) => rows.length > 0);
  if (!row) throw new SubmissionError('NOT_FOUND', 'Leaf not found for this organization/sequence.');

  // Part 11 §11.10(e). The soft delete above is committed and is not reinstated
  // when this write fails: un-deleting the leaf would put a document back into a
  // sequence the operator removed it from, which is a worse answer than a lost
  // log row. The action stands and the caller is told.
  const auditTrail = await recordAuditRow({
    organizationId: ctx.organizationId,
    userId: ctx.userId,
    action: 'LEAF_REMOVED',
    resourceType: 'submission_leaf',
    resourceId: leafId,
    details: { sequenceId, sectionCode: row.sectionCode, ...(reason ? { reason } : {}) },
  });
  const sequenceStatusChanged = revertedFromValidated ? await recordRevertedValidation(sequenceId, leafId, ctx) : undefined;
  return { leafId, auditTrail, ...(sequenceStatusChanged ? { sequenceStatusChanged } : {}) };
}

export default {
  createSubmission,
  createSubmissionTx,
  listSubmissions,
  getSubmission,
  createSequence,
  listSequences,
  transitionSequence,
  listLeaves,
  upsertLeaf,
  removeLeaf,
  canTransitionSequence,
  isSequenceLocked,
  SubmissionError,
};
